  'We had already received this receipt, thank you 🌱 We\'ll get back to you about your payment as soon as possible.' => 'Мы уже получили эту квитанцию, спасибо 🌱 Мы свяжемся с вами по поводу оплаты как можно скорее.',
  'This receipt seems to have been uploaded to our system before. The same receipt cannot be used for a second donation. If you made a different payment, please send that receipt; our team will also check.' => 'Похоже, эта квитанция уже была загружена в нашу систему ранее. Эту же квитанцию ​​нельзя использовать для второго пожертвования. Если вы произвели другой платеж, отправьте эту квитанцию; наша команда также проверит.',
  'We received your receipt. The amount on it (%1$s) does not seem to match your donation amount (%2$s). Could you check it? If you made a different payment, you can write here; our team will also take a look.' => 'Мы получили вашу квитанцию. Сумма на нем (%1$s), похоже, не соответствует сумме вашего пожертвования (%2$s). Не могли бы вы это проверить? Если вы произвели другой платеж, вы можете написать здесь; наша команда также рассмотрит.',
  'We received your receipt, but the recipient on it does not seem to be our association. Donations are only made to our account in the name of "%s". Could you check? Our team will also take a look.' => 'Мы получили вашу квитанцию, но получатель на ней, похоже, не является нашей ассоциацией. Пожертвования переводятся на наш счет только на имя «%s». Не могли бы вы проверить? Наша команда тоже присмотрится.',
  'We received your receipt, but the recipient on it does not seem to match our account. Could you check? Our team will also take a look.' => 'Мы получили вашу квитанцию, но получатель на ней, похоже, не соответствует нашему аккаунту. Не могли бы вы проверить? Наша команда тоже присмотрится.',
  'The file you sent does not look like a payment receipt. If you have paid, you can send the receipt or a screenshot of the payment screen here.' => 'Отправленный вами файл не похож на квитанцию об оплате. Если вы произвели оплату, вы можете отправить сюда квитанцию ​​или скриншот экрана оплаты.',
