  'no number' => 'нет номера',
  'Motivational lines (one per line; one is added at random to each report)' => 'Мотивационные строки (по одной в каждой строке; одна добавляется в каждый отчет случайным образом)',
  '%d recipients (with a registered number and permission).' => 'Получатели %d(с зарегистрированным номером и разрешением).',
  'Last sent: %s.' => 'Последняя отправка: %s.',
  'Preview (for you)' => 'Предварительный просмотр (для вас)',
  'Send me a test' => 'Отправьте мне тест',
  'Send the report to all recipients now?' => 'Отправить отчет всем получателям сейчас?',
  'Send to everyone now' => 'Отправить всем сейчас',
  'Delete this report?' => 'Удалить этот отчет?',
  '+ New report' => '+ Новый отчет',
  'The recipient\'s number comes from Users › Profile › WhatsApp number; permissions from Users › Roles and access (receive reports, view overall report, manage reports). Reports go out at the chosen time; without a server scheduler they are sent on the next site visit or chat panel use.' => 'Номер получателя берется из Пользователи › Профиль › Номер WhatsApp; разрешения пользователей › Роли и доступ (получение отчетов, просмотр общего отчета, управление отчетами). Отчеты выходят в выбранное время; без планировщика сервера они отправляются при следующем посещении сайта или использовании панели чата.',
  'Invalid phone number.' => 'Неверный номер телефона.',
  'First add a WhatsApp connection under Settings › Connections.' => 'Сначала добавьте соединение WhatsApp в разделе «Настройки» > «Подключения».',
  '%1$s assigned the chat to %2$s' => '%1$s назначил чат пользователю %2$s.',
  '%s removed the chat assignment' => '%s удалил назначение чата',
  '%s closed the chat' => '%s закрыл чат',
  '%s reopened the chat' => '%s вновь открыл чат',
  'File is too large (max %s).' => 'Файл слишком велик (максимум %s).',
  'This file type cannot be sent.' => 'Этот тип файла не может быть отправлен.',
  'File could not be uploaded.' => 'Не удалось загрузить файл.',
  'This message cannot be resent.' => 'Это сообщение нельзя отправить повторно.',
  'Can\'t react to this message.' => 'Не могу отреагировать на это сообщение.',
  'You can only delete your own notes.' => 'Вы можете удалять только свои заметки.',
  'Reply text cannot be empty.' => 'Текст ответа не может быть пустым.',
  'Connection not found. Save the settings first.' => 'Соединение не найдено. Сначала сохраните настройки.',
  'The message was only image code; it was not sent.' => 'Сообщение представляло собой всего лишь код изображения; оно не было отправлено.',
  'This contact is blocklisted; no messages are sent. Remove them from the blocklist to write again.' => 'Этот контакт занесен в черный список; никакие сообщения не отправляются. Удалите их из черного списка, чтобы написать снова.',
  'Message could not be saved.' => 'Сообщение не удалось сохранить.',
  'This contact writes from a hidden WhatsApp number (@lid) and Evolution API (version %s) could not send to this address. Update the Evolution API server to 2.3 or later; if the contact\'s real number arrives, the plugin sends there.' => 'Этот контакт пишет со скрытого номера WhatsApp (@lid) и Evolution API (версия %s) не смог отправить на этот адрес. Обновите сервер Evolution API до версии 2.3 или новее; если приходит реальный номер контакта, плагин отправляет туда.',
  'This contact writes from a hidden WhatsApp number (@lid) and Evolution API could not send to this address. Update the Evolution API server to 2.3 or later; if the contact\'s real number arrives, the plugin sends there.' => 'Этот контакт пишет со скрытого номера WhatsApp (@lid), и Evolution API не смог отправить сообщение на этот адрес. Обновите сервер Evolution API до версии 2.3 или новее; если приходит реальный номер контакта, плагин отправляет туда.',
  'No WhatsApp connection.' => 'Нет подключения к WhatsApp.',
  'Connected ✓' => 'Подключено ✓',
  'Not connected (state: %s). Connect with QR.' => 'Не подключено (состояние: %s). Подключитесь с помощью QR.',
  'Webhook points to this site ✓' => 'Webhook указывает на этот сайт ✓',
  'Evolution API version: %s' => 'Версия API эволюции: %s.',
  '(old: replies to hidden-number (@lid) contacts may fail, update to 2.3 or later)' => '(старая версия: ответы на контакты со скрытым номером (@lid) могут не получиться, обновите до версии 2.3 или более поздней)',
  'The webhook is not pointed at this site. Press "Set up webhook".' => 'Вебхук не направлен на этот сайт. Нажмите «Настроить вебхук».',
  'Webhook set up ✓ Incoming messages will now arrive here.' => 'Настройка вебхука ✓ Теперь входящие сообщения будут поступать сюда.',
  'Importing recent chats, this may take a while…' => 'Импорт последних чатов. Это может занять некоторое время...',
  'Messages stored in Evolution: %s' => 'Сообщения, хранящиеся в Evolution: %s',
  'Evolution does not store messages, so older messages cannot be loaded. On the Evolution server set DATABASE_SAVE_DATA_NEW_MESSAGE and DATABASE_SAVE_DATA_HISTORIC to true; for older conversations, keep "Sync full history" on in the instance settings when you reconnect the line with QR.' => 'Evolution не хранит сообщения, поэтому старые сообщения загрузить невозможно. На сервере Evolution установите для DATABASE_SAVE_DATA_NEW_MESSAGE и DATABASE_SAVE_DATA_HISTORIC значение true; для более старых разговоров оставьте включенным параметр «Синхронизировать полную историю» в настройках экземпляра при повторном подключении линии с помощью QR.',
  '%1$s chats, %2$s messages imported ✓' => 'Импортированы чаты %1$s, сообщения %2$s✓',
  'Scan this code via WhatsApp › Linked devices › Link a device.' => 'Отсканируйте этот код через WhatsApp › Связанные устройства › Привяжите устройство.',
  'Pairing code:' => 'Код сопряжения:',
  'This line is already connected ✓' => 'Эта линия уже подключена ✓',
  'Save the settings first.' => 'Сначала сохраните настройки.',
  'Error:' => 'Ошибка:',
  'Delete this connection? Chat history is kept.' => 'Удалить это соединение? История чата сохраняется.',
  'Asking the AI…' => 'Спросить ИИ...',
  'Working ✓ (%2$s ms): %1$s' => 'Работает ✓ (%2$s мс): %1$s',
  'Save the key and model first.' => 'Сначала сохраните ключ и модель.',
  'Connections' => 'Соединения',
  'Auto replies' => 'Автоответы',
  'AI and assistant' => 'ИИ и помощник',
  'System check' => 'Проверка системы',
  'Connect your WhatsApp line, manage auto replies and labels.' => 'Подключите свою линию WhatsApp, управляйте автоответами и метками.',
  'Open chats' => 'Открытые чаты',
  'Settings saved.' => 'Настройки сохранены.',
  'Connections and settings the call center needs. Saved status is shown; use the "test" buttons on each tab for a live check. The same checks also appear with the other plugins on the theme\'s system-check screen.' => 'Соединения и настройки, необходимые колл-центру. Отображается сохраненный статус; используйте кнопки «тест» на каждой вкладке для проверки в реальном времени. Те же проверки отображаются и с другими плагинами на экране проверки системы темы.',
  'WhatsApp lines' => 'Линии WhatsApp',
  'Messages are sent and received through Evolution API. WhatsApp connections are managed in Flux Mail; choose which one to use here. The URL and API key stay there, so you do not need to update them here when they change.' => 'Сообщения отправляются и принимаются через Evolution API. Подключения WhatsApp управляются в Flux Mail; выберите, какой из них использовать здесь. URL-адрес и ключ API остаются там, поэтому вам не нужно обновлять их здесь при их изменении.',
  'Communication › Connections' => 'Связь › Соединения',
  'Messages are sent and received via Evolution API. If an Evolution provider is set up in Flux Certificates, you can pick the same connection; the URL and API key stay there.' => 'Сообщения отправляются и принимаются через Evolution API. Если провайдер Evolution настроен в сертификатах Flux, вы можете выбрать то же соединение; URL-адрес и ключ API остаются там.',
  'Add line' => 'Добавить строку',
  'Setup steps' => 'Шаги настройки',
  'Add the line and save.' => 'Добавьте строку и сохраните.',
  'Use "Test connection" to see that Evolution is reachable. If the line is not linked, choose "Connect with QR" and scan it from the phone.' => 'Используйте «Проверочное соединение», чтобы убедиться, что Evolution доступен. Если линия не связана, выберите «Подключиться с помощью QR» и отсканируйте ее с телефона.',
  'Press "Set up webhook". Incoming messages, and messages sent from the phone and from Flux Certificates, then appear here live.' => 'Нажмите «Настроить вебхук». Входящие сообщения и сообщения, отправленные с телефона и из сертификатов Flux, затем появляются здесь в прямом эфире.',
  'Optionally bring in past messages with "Import recent chats".' => 'При желании можно добавить прошлые сообщения с помощью «Импортировать последние чаты».',
