  'Appearance' => 'Внешний вид',
  'Panel title' => 'Название панели',
  'Site name if empty. The {brand} variable uses this too.' => 'Имя сайта, если пусто. Переменная {brand} также использует это.',
  'Accent color' => 'Акцентный цвет',
  'Behavior' => 'Поведение',
  'Send read receipts (blue ticks) when a chat is opened' => 'Отправлять уведомления о прочтении (синие галочки) при открытии чата',
  'Prefix messages with the agent\'s name (*Name:*)' => 'Префикс сообщений с именем агента (*Имя:*)',
  'Agents see only chats assigned to them and unassigned chats (admins see all)' => 'Агенты видят только назначенные им чаты и неназначенные чаты (администраторы видят все)',
  'Also show WhatsApp group messages' => 'Также показывать групповые сообщения WhatsApp',
  'New interface (experimental): the Chats page opens with the same screen as the desktop and mobile app' => 'Новый интерфейс (экспериментальный): страница чатов открывается на том же экране, что и настольное и мобильное приложение.',
  'Live update interval (sec)' => 'Интервал обновления в реальном времени (сек)',
  'Agents' => 'Агенты',
  'Give a user the %s role; they see only the chat screen and cannot open settings. Administrators always have access.' => 'Назначьте пользователю роль %s; они видят только экран чата и не могут открыть настройки. Администраторы всегда имеют доступ.',
  'Add new user' => 'Добавить нового пользователя',
  'Data' => 'Данные',
  'Also delete all chats, messages and media files when the plugin is deleted' => 'Также удалите все чаты, сообщения и медиафайлы при удалении плагина.',
  'Media files are kept in wp-content/uploads/flx-chat, closed to outside access. They move with uploads when the site is migrated.' => 'Медиа-файлы хранятся в папке wp-content/uploads/flx-chat и закрыты для внешнего доступа. Они перемещаются вместе с загрузками при переносе сайта.',
