  'At most once per contact every (hours)' => 'Не более одного раза за контакт каждые (часы)',
  'Timezone: %1$s. Now: %2$s.' => 'Часовой пояс: %1$s. Сейчас: %2$s.',
  'within business hours' => 'в рабочее время',
