  'The {first_name}, {name}, {brand}, {site}, {date} variables can be used in the texts.' => 'В текстах можно использовать переменные {first_name}, {name}, {brand}, {site}, {date}.',
  'Chat labels' => 'Chat labels',
  'Label chats and filter the list (e.g. Donation, Complaint, Follow-up).' => 'Пометьте чаты и отфильтруйте список (например, «Пожертвование», «Жалоба», «Последующие действия»).',
  'Add label' => 'Добавить ярлык',
  'Label name' => 'Название ярлыка',
  'Creating records from chats' => 'Создание записей из чатов',
  'Buttons in the chat header create a donation record (Flux Donate) and a certificate (Flux Certificates), and an incoming receipt is matched with a record. If a plugin is not installed, its button is hidden.' => 'Кнопки в шапке чата создают запись о пожертвовании (Flux Donate) и сертификат (Flux Certificates), а входящая квитанция сопоставляется с записью. Если плагин не установлен, его кнопка скрыта.',
  'Agents can create donation records and match receipts' => 'Агенты могут создавать записи о пожертвованиях и сопоставлять квитанции.',
  'Agents can create and send certificates' => 'Агенты могут создавать и отправлять сертификаты',
  'Show quick reply bubbles above the message box' => 'Показывать всплывающие окна быстрого ответа над окном сообщения',
  'Donation messages' => 'Сообщения о пожертвованиях',
  'Ready texts sent to the person when a record is created (editable before sending). If left empty, the default text is used.' => 'Готовые тексты отправляются человеку при создании записи (редактируются перед отправкой). Если оставить пустым, используется текст по умолчанию.',
  'Awaiting payment (promised transfer)' => 'Ожидание платежа (обещанный перевод)',
  'Donation received' => 'Пожертвование получено',
  'Receipt confirmed' => 'Получение подтверждено',
  'Bank details ({bank})' => 'Банковские реквизиты ({bank})',
  'Recipient name, bank, IBAN' => 'Имя получателя, банк, IBAN',
  'If empty, the account in WooCommerce › Payments › Bank transfer is used.' => 'Если пусто, используется учетная запись в WooCommerce › Платежи › Банковский перевод.',
  'Variables: {first_name}, {name}, {donation}, {amount}, {quantity}, {bank}, {certificate_link}, {agent}, {brand}, {date}.' => 'Переменные: {first_name}, {name}, {donation}, {amount}, {quantity}, {bank}, {certificate_link}, {agent}, {brand}, {date}.',
  'AI connection' => 'AI-соединение',
  'Keys, prompt caching, spending limits and usage logs come from the Flux AI & MCP plugin; all of the Call Center\'s AI requests go through it. Model choices stay here; if a field is empty, the model chosen for this plugin in Flux AI (or the default) is used.' => 'Ключи, оперативное кэширование, лимиты расходов и журналы использования поступают из плагина Flux AI & MCP; все запросы ИИ колл-центра проходят через него. Выбор модели остается здесь; если поле пусто, используется модель, выбранная для этого плагина в Flux AI (или модель по умолчанию).',
  'Open Flux AI settings' => 'Откройте настройки Flux AI.',
  'AI needs the Flux AI & MCP plugin. Install and activate it, then enter the OpenRouter and/or Anthropic key in Flux AI & MCP › Settings. Until then suggestions, the assistant, receipt reading, voice messages and summaries are off.' => 'ИИ нужен плагин Flux AI & MCP. Установите и активируйте его, затем введите ключ OpenRouter и/или Anthropic в Flux AI & MCP › Настройки. До этого момента предложения, помощник, чтение квитанций, голосовые сообщения и сводки отключены.',
  'Creativity (0–1)' => 'Креативность (0–1)',
  'Lower values give more consistent replies, higher values freer ones. 0.4 recommended.' => 'Более низкие значения дают более последовательные ответы, более высокие — более свободные. рекомендуется 0,4.',
  'Model (for suggestions)' => 'Модель (для предложений)',
  'Assistant model (optional)' => 'Модель помощника (опционально)',
  'Model above' => 'Модель выше',
  'Only models that support tools are listed.' => 'В списке указаны только модели, поддерживающие инструменты.',
  'Receipt reading model (optional)' => 'Модель чтения квитанции (опционально)',
  'If the selected model cannot read images, a cheap vision model is used automatically.' => 'Если выбранная модель не может читать изображения, автоматически используется дешевая модель зрения.',
  'This month (%1$s): %2$s requests, %3$s tokens, about $%4$s.' => 'В этом месяце (%1$s): запросы %2$s, токены %3$s, около $%4$s.',
  'Reply suggestions' => 'Ответить на предложения',
  'Above the message box, the next message is suggested from the conversation. The agent clicks "Send" or takes it into the box with "Edit". A suggestion is never sent on its own.' => 'Над окном сообщения предлагается следующее сообщение из беседы. Агент нажимает «Отправить» или переносит в поле «Редактировать». Предложение никогда не отправляется само по себе.',
  'Prepare a suggestion automatically when the last message came from the person (if off, ask with the ✨ button)' => 'Подготовьте предложение автоматически, когда пришло последнее сообщение от человека (если выключено, спросите кнопкой ✨)',
  'Organization info and tone' => 'Информация об организации и тон',
  'E.g. Our association plants saplings in Istanbul. Planting is done every year between November and March. The certificate is sent on WhatsApp after the donation. Use a warm but formal tone.' => 'например Наша ассоциация сажает саженцы в Стамбуле. Посадка производится каждый год в период с ноября по март. Сертификат отправляется на WhatsApp после пожертвования. Используйте теплый, но формальный тон.',
  'Suggestions and the assistant use this. Donation types, prices, bank details and quick replies are added automatically.' => 'Предложения и помощник используют это. Типы пожертвований, цены, банковские реквизиты и быстрые ответы добавляются автоматически.',
  'Suggestion provider' => 'Поставщик предложений',
  'Donation assistant (automatic replies)' => 'Помощник по пожертвованиям (автоматические ответы)',
  'When on, the assistant replies itself: it greets, asks the name to address them, sends donation options and prices, optionally collects email and "in whose name", and asks for confirmation after each change. After confirmation it opens an "awaiting payment" record in Flux Donate and sends the donation link, recipient, IBAN and reference as separate messages. If the topic leaves donations, it hands the chat to the team.' => 'При включении помощник отвечает сам: приветствует, спрашивает имя для обращения, отправляет варианты пожертвований и цены, при необходимости собирает электронную почту и «от чьего имени» и запрашивает подтверждение после каждого изменения. После подтверждения он открывает запись «ожидает платежа» в Flux Donate и отправляет ссылку для пожертвования, получателя, IBAN и ссылку в виде отдельных сообщений. Если тема оставляет пожертвования, она передает чат команде.',
  'The Flux Donate plugin is not active; the assistant cannot create donation records.' => 'Плагин Flux Donate не активен; помощник не может создавать записи о пожертвованиях.',
  'Instructions, documents, AI chats and test chat' => 'Инструкции, документы, AI-чаты и тестовый чат',
  'Turn on the donation assistant (untick to turn it off everywhere)' => 'Включите помощника по пожертвованиям (снимите галочку, чтобы отключить его везде)',
  'Which chats should it reply to' => 'В каких чатах он должен отвечать',
  'In all chats (recommended)' => 'Во всех чатах (рекомендуется)',
  'In chats not assigned to an agent' => 'В чатах, не закрепленных за агентом',
  'Only outside working hours' => 'Только вне рабочего времени',
  'When an agent writes in a chat (from the panel or the phone), the assistant stays quiet there for the time below. Use the assistant button in the chat header to turn it on or off per chat.' => 'Когда агент пишет в чат (с панели или телефона), ассистент молчит там указанное ниже время. Используйте кнопку помощника в заголовке чата, чтобы включить или выключить его для каждого чата.',
  'Test mode: reply only to the numbers below' => 'Тестовый режим: отвечайте только на номера ниже',
  'Test numbers' => 'Номера тестов',
  'Separate with commas or new lines. Not used when test mode is off.' => 'Разделяйте запятыми или новыми строками. Не используется, если тестовый режим выключен.',
  'Quiet after an agent writes (hours)' => 'Тишина после того, как агент напишет (часы)',
  'Quantities in the price list' => 'Количество в прайс-листе',
  'Conversation history (hours)' => 'История разговоров (часы)',
  'Before replying, the assistant reads all messages from this period.' => 'Прежде чем ответить, помощник читает все сообщения за этот период.',
  'Donation types the assistant offers' => 'Виды пожертвований, которые предлагает помощник',
  'If none is selected, all open types are offered. When a new type is opened in Flux Donate, the assistant knows it too.' => 'Если ничего не выбрано, предлагаются все открытые типы. Когда в Flux Donate открывается новый тип, помощник тоже об этом узнает.',
  'Receipt pre-check: when the contact sends a receipt, AI compares the amount, recipient and IBAN with the donation, tells the contact the result, attaches the file to the donation record and hands the chat to the team for final approval (does not mark it paid)' => 'Предварительная проверка квитанции: когда контакт отправляет квитанцию, AI сравнивает сумму, получателя и IBAN с пожертвованием, сообщает контакту результат, прикрепляет файл к записи о пожертвовании и передает чат команде для окончательного утверждения (не помечает его как оплаченного)',
  'Last line of the price list' => 'Последняя строка прайс-листа',
  'Payment details' => 'Детали оплаты',
  'If the recipient and IBAN are empty, those in WooCommerce › Payments › Bank transfer are used (the account shown on orders). Fill them in only if the assistant should use a different account.' => 'Если получатель и IBAN пусты, используются те, которые указаны в WooCommerce › Платежи › Банковский перевод (счет, указанный в заказах). Заполняйте их только в том случае, если помощник должен использовать другую учетную запись.',
  'Recipient name' => 'Имя получателя',
  'Transfer description' => 'Описание трансфера',
  'Variables: {type}, {name}, {amount}, {quantity}' => 'Переменные: {type}, {name}, {amount}, {quantity}.',
  'Donation page URL' => 'URL страницы пожертвований',
  'The selected type and quantity are added to the link (?flxb_opt=…&flxb_qty=…).' => 'Выбранный тип и количество добавляются в ссылку (?flxb_opt=...&flxb_qty=...).',
  'Message after the payment details' => 'Сообщение после платежных реквизитов',
  'Donation cancellation question' => 'Вопрос об отмене пожертвования',
  'The assistant cancels only unpaid donations, with the person\'s confirmation. Empty = default text. Variables: {bagis}, {tutar}.' => 'Помощник отменяет только неоплаченные пожертвования с согласия человека. Пусто = текст по умолчанию. Переменные: {bagis}, {tutar}.',
  'Message sent when the daily limit is reached' => 'Сообщение отправляется при достижении дневного лимита',
  'Sent once when a chat reaches the day\'s reply limit; the chat is handed to the team. Reset it from the chat\'s ⋮ menu › Assistant usage.' => 'Отправляется один раз, когда в чате достигнут дневной лимит ответов; чат передается команде. Сбросьте его из меню ⋮ чата › Использование Ассистента.',
  'Message sent when handing over to the team' => 'Сообщение, отправленное при передаче команде',
  'Message sent when the assistant cannot answer' => 'Сообщение отправляется, когда помощник не может ответить',
  'If the AI fails, the time limit is hit or the queue gets too long, this message is sent and the chat is handed to the team; the person is never left without an answer.' => 'Если ИИ дает сбой, истекает лимит времени или очередь становится слишком длинной, это сообщение отправляется, и чат передается команде; человек никогда не остается без ответа.',
  'Minimum wait before the holding message (s)' => 'Минимальное ожидание перед сообщением(ями) об удержании',
  'The holding message is not sent until this many seconds after the person\'s message; meanwhile the assistant retries.' => 'Сообщение об удержании не отправляется до истечения этого количества секунд после сообщения человека; тем временем помощник повторяет попытку.',
  'Longest time for one answer (s)' => 'Самое долгое время для одного ответа(ов)',
  'Hostinger can cut requests at ~60 s; 50 is recommended.' => 'Hostinger может обрезать запросы примерно за 60 с; рекомендуется 50.',
  'Numbers notified on handoff' => 'Номера уведомлены о передаче',
  'When the assistant hands a chat over to the team, a WhatsApp message is sent to these numbers from the same line: the contact\'s name, phone, reason, last messages and panel link. Separate with commas or new lines. The assistant does not talk to these numbers.' => 'Когда ассистент передает чат команде, на эти номера с одной линии отправляется сообщение WhatsApp: имя контакта, телефон, причина, последние сообщения и ссылка на панель. Разделяйте запятыми или новыми строками. Ассистент не разговаривает по этим номерам.',
  'When the contact writes one of these, the assistant immediately sends the hand-off message above and turns off in that chat. If left empty, the example list is used.' => 'Когда контакт пишет одно из них, помощник немедленно отправляет сообщение о переключении связи, указанное выше, и отключается в этом чате. Если оставить пустым, используется список примеров.',
  'Extra instructions for the assistant' => 'Дополнительные инструкции для помощника',
  'E.g. Saplings are planted in Kocaeli. Certificates are sent once the donation is confirmed.' => 'например Саженцы посажены в Коджаэли. Сертификаты высылаются после подтверждения пожертвования.',
  'Last message when a contact opts out' => 'Последнее сообщение, когда контакт отказывается от подписки',
  'If someone writes something like "don\'t message me", the assistant sends this message and blocklists them. A blocklisted person gets no WhatsApp, email or SMS; manage the list under Chats › ☰ › Blocklist.' => 'Если кто-то напишет что-то вроде «не писать мне», помощник отправит это сообщение и занесет его в черный список. Человек, занесенный в черный список, не получает WhatsApp, электронной почты или SMS; управляйте списком в разделе «Чаты» › ☰ › Черный список.',
  'Contact memory and background jobs' => 'Память контактов и фоновые задания',
  'Contact memory: the assistant remembers lasting details (form of address, relatives\' names, numbers, preferences); expired chats are summarized' => 'Контактная память: ассистент запоминает устойчивые детали (форму обращения, имена родственников, номера телефонов, предпочтения); просроченные чаты суммируются',
  'Summarize a chat after it has been quiet for (hours)' => 'Подведите итоги чата после того, как в нем было тихо в течение (часов)',
  'Maximum jobs at the same time' => 'Максимальное количество рабочих мест одновременно',
  'How many people can be answered at the same time. Assistant replies always come first; summaries do not start while someone is being answered or waiting. Each job uses one PHP worker: on shared hosting, stay under half of the total worker limit of your sites (e.g. 20-30 of 60 workers).' => 'Скольким людям можно ответить одновременно. Ответы Ассистента всегда на первом месте; сводки не запускаются, пока кому-то отвечают или ждут. В каждом задании используется один PHP-воркер: на общем хостинге не превышайте половину общего лимита рабочих на ваших сайтах (например, 20–30 из 60 рабочих).',
  'Workers reserved for replies' => 'Рабочие зарезервированы для ответов',
  'This many workers never take summaries or reminders.' => 'Многие работники никогда не принимают конспекты и напоминания.',
  'Summary hours' => 'Суммарные часы',
  'Summaries run only between these hours (except a manual "Summarize now"). If both are the same, any time.' => 'Сводки публикуются только в эти часы (кроме инструкции «Подвести итоги сейчас»). Если оба одинаковы, в любое время.',
  'When someone sends a voice message, the assistant turns it into text and replies (the text also appears in the panel as a system line)' => 'Когда кто-то отправляет голосовое сообщение, помощник преобразует его в текст и отвечает (текст также отображается в панели в виде системной строки)',
  'Longest voice message (sec)' => 'Самое длинное голосовое сообщение (сек)',
  'For longer messages the assistant says "the voice message was too long for us to listen to".' => 'В случае более длинных сообщений помощник говорит: «Голосовое сообщение было слишком длинным, чтобы мы могли его прослушать».',
  'Voice message model (optional)' => 'Модель голосового сообщения (необязательно)',
  'Cheap audio model (Gemini Flash Lite)' => 'Дешевая аудиомодель (Gemini Flash Lite)',
  'Must be an OpenRouter model that accepts audio (Claude does not). An OpenRouter key is required.' => 'Должна быть модель OpenRouter, которая принимает аудио (Клод не принимает). Требуется ключ OpenRouter.',
  'Images' => 'Изображения',
  'Let the assistant draw an image when useful (table, report, diagram); it goes to WhatsApp as a picture, the text is sent separately' => 'Пусть помощник нарисует изображение, когда это будет полезно (таблица, отчет, диаграмма); в WhatsApp он отправляется в виде картинки, текст отправляется отдельно',
  'The Flux AI image renderer is used (Flux AI & MCP › Settings › Images).' => 'Используется рендеринг изображений Flux AI (Flux AI & MCP › Настройки › Изображения).',
  'No image renderer on the server: enter a Gotenberg address in Flux AI & MCP › Settings › Images or install Imagick (SVG). Until then the assistant does not draw images.' => 'На сервере нет средства рендеринга изображений: введите адрес Готенберга в Flux AI & MCP › Настройки › Изображения или установите Imagick (SVG). До этого момента помощник не рисует изображения.',
  'Works once Flux AI 0.2.0 or later is installed.' => 'Работает после установки Flux AI 0.2.0 или новее.',
  'Donation on behalf of someone' => 'Пожертвование от имени кого-либо',
  'If the donation is in someone else\'s name and their number was given (contact card or typed number), also send the certificate to that number on WhatsApp once the payment is approved' => 'Если пожертвование сделано на чье-то имя и был указан его номер (контактная карточка или введенный номер), также отправьте сертификат на этот номер в WhatsApp после подтверждения платежа.',
  'Message sent before the certificate' => 'Сообщение отправлено перед сертификатом',
  'Then the WhatsApp certificate message from Flux Certificates is sent. Variables: {ad}, {bagisci}, {bagis}, {brand}.' => 'Затем отправляется сообщение сертификата WhatsApp от Flux Certificates. Переменные: {ad}, {bagisci}, {bagis}, {brand}.',
  'If a person asks, the assistant sets up a reminder (e.g. "remind me of sapling planting every month", "send me your latest projects every month", "ask me for a sapling every month"); when it is due, the assistant writes and sends the message' => 'Если человек спрашивает, помощник устанавливает напоминание (например, «напоминай мне о посадке саженцев каждый месяц», «присылай мне свои последние проекты каждый месяц», «проси у меня саженец каждый месяц»); когда наступит срок, помощник напишет и отправит сообщение',
  'When no time is given' => 'Когда времени не дано',
  'At most per person' => 'Максимум на человека',
  'Staff (Flux Roles)' => 'Персонал (роли Flux)',
  'Works once Flux Roles 1.1.0 is installed: users whose number is set in Profile › WhatsApp number get extra assistant tools based on their permissions.' => 'Работает после установки Flux Roles 1.1.0: пользователи, номер которых указан в Профиле › Номер WhatsApp, получают дополнительные вспомогательные инструменты в зависимости от их разрешений.',
  'Give staff numbers extra assistant tools by permission (donation on behalf of someone with payment link, my donors, general report)' => 'Предоставьте сотрудникам дополнительные вспомогательные инструменты с разрешения (пожертвование от имени человека, у которого есть ссылка на оплату, моих доноров, общий отчет)',
  'Notify staff on WhatsApp when a donation they referred is paid or cancelled' => 'Уведомляйте сотрудников в WhatsApp, когда пожертвование, на которое они ссылаются, оплачено или отменено.',
  'First message to the donor for a donation opened by staff' => 'Первое сообщение донору о пожертвовании, открытое сотрудниками',
  'Hello {ad} 🌱 Your {bagis} donation request via {personel} has been received. You can pay with the details below.' => 'Привет, {ad}🌱 Ваш запрос на пожертвование {bagis} через {personel} получен. Вы можете оплатить по реквизитам ниже.',
  'The payment link and bank details follow. Variables: {ad}, {adsoyad}, {personel}, {bagis}.' => 'Далее следует ссылка для оплаты и банковские реквизиты. Переменные: {ad}, {adsoyad}, {personel}, {bagis}.',
  'When a donation referred by a staff member is paid and its certificates are made, send them to the staff member on WhatsApp too (just like the donor)' => 'Когда пожертвование, указанное сотрудником, будет оплачено и получены сертификаты, отправьте их также сотруднику в WhatsApp (так же, как и донору).',
  'Message sent to the staff member before the certificate' => 'Сообщение, отправленное сотруднику перед сертификатом',
  'Variables: {ad}, {bagisci}, {bagis}, {no}, {brand}.' => 'Переменные: {ad}, {bagisci}, {bagis}, {no}, {brand}.',
  'How many times staff can resend a donation\'s certificate' => 'Сколько раз сотрудники могут повторно отправить сертификат о пожертвовании',
  'The assistant lists the recipients and asks for confirmation before sending. 0: off.' => 'Помощник перечисляет получателей и запрашивает подтверждение перед отправкой. 0: выкл.',
  'Code verification for record lookups' => 'Проверка кода для поиска записей',
  'When a person asks for their records and their number is hidden (or they donated with another number/e-mail), send a code to the number or e-mail they give; once verified, its records are shown too' => 'Когда человек запрашивает свои записи, а его номер скрыт (или он сделал пожертвование с помощью другого номера/электронной почты), отправьте код на указанный им номер или адрес электронной почты; после проверки его записи также отображаются',
  'Code validity (min)' => 'Срок действия кода (мин)',
  'Maximum failed attempts' => 'Максимальное количество неудачных попыток',
  'Codes that could not be sent, wrong codes and expired codes count. At the limit the person gets the message below and the team is notified; the assistant keeps answering other questions but shares no record details for 24 hours.' => 'Учитываются коды, которые не удалось отправить, неправильные коды и коды с истекшим сроком действия. При достижении лимита человек получает сообщение ниже, и команда уведомляется; помощник продолжает отвечать на другие вопросы, но не сообщает никаких подробностей в течение 24 часов.',
  'Code to phone' => 'Код на телефон',
