  'Site content' => 'Содержание сайта',
  'Let the assistant search published site content (e.g. "do you have a post about tree planting")' => 'Разрешите помощнику выполнять поиск по опубликованному контенту сайта (например, «есть ли у вас запись о посадке деревьев»).',
  'Content types to search' => 'Типы контента для поиска',
  'Only published content without a password is returned. Drafts, private and password-protected content are never shown.' => 'Возвращается только опубликованный контент без пароля. Черновики, личный контент и контент, защищенный паролем, никогда не отображаются.',
  'Categories and tags never to share' => 'Категории и теги, которыми нельзя делиться',
  'e.g. corporate-offers, internal-notice' => 'например корпоративные предложения, внутреннее уведомление',
