  'Handoff' => 'Передача',
  'Only real chats are counted; test chat and benchmark are excluded. "Confirmed" means donations created by the assistant and marked paid.' => 'Учитываются только реальные чаты; тестовый чат и тест исключены. «Подтверждено» означает пожертвования, созданные помощником и помеченные как оплаченные.',
