  'Assistant instructions' => 'Инструкции помощника',
  'The main text describing how the assistant talks and the flow. Prices, donation types, bank details and what is known about the contact are added automatically on every reply. {brand} becomes the organisation name and {{belge:kisa-ad}} becomes that document\'s content.' => 'Основной текст, описывающий, как говорит ассистент и как он движется. Цены, типы пожертвований, банковские реквизиты и сведения о контакте добавляются автоматически при каждом ответе.{brand} становится названием организации, а {{belge:kisa-ad}} становится содержимым этого документа.',
