  'Full text sent to the model (sample chat)' => 'Полный текст отправлен модели (пример чата)',
  'Extra documents' => 'Дополнительные документы',
  'Add FAQs, campaigns, planting locations and similar information as separate documents. If you write {{belge:kisa-ad}} in the instructions, the document is placed there. A document set to "read when needed" is only read when the topic comes up, which costs less for long documents.' => 'Добавляйте часто задаваемые вопросы, кампании, места посадки и аналогичную информацию в отдельные документы. Если в инструкции написать {{belge:kisa-ad}}, документ помещается туда. Документ, настроенный на «чтение при необходимости», читается только тогда, когда возникает тема, что обходится дешевле для длинных документов.',
