  'E.g. Look at Ahmet\'s chat and make the price answer shorter. / Hand over to the team when asked about Qurban donations.' => 'например Посмотрите чат Ахмета и сделайте ответ по цене короче. / Передайте команду, когда вас спросят о пожертвованиях к Курбану.',
