  '{n} chats queued' => '{n} чаты в очереди',
  'Contact memory is off; summary jobs do not run.' => 'Память контактов отключена; сводные задания не запускаются.',
  'Summaries paused for 30 minutes: {r}' => 'Сводки приостановлены на 30 минут: {r}.',
  'Running workers' => 'Бегущие рабочие',
  'Chats being answered' => 'В чатах отвечают',
  'Chats being summarized' => 'Чаты суммируются',
  'Queued' => 'В очереди',
  'Chats not yet expired' => 'Срок действия чатов еще не истек',
  'Summaries today · USD' => 'Сводки сегодня · USD',
  'Recent jobs' => 'Недавние вакансии',
  'Scan now' => 'Сканировать сейчас',
  'People who are writing are answered first; no summary starts while someone is being answered or waiting. Chats quiet for {h} hours are summarized only between {w}. At most {m} jobs run at once, {r} workers are reserved for replies (a benchmark counts as one). Refreshes every 5 s.' => 'Пишущим отвечают первыми; сводка не начинается, пока кому-то отвечают или ждут. Чаты, молчащие в течение {h} часов, суммируются только между {w}. В большинстве случаев {m} задания выполняются одновременно, работники {r} зарезервированы для ответов (тест считается за один). Обновляется каждые 5 с.',
