  'Per scenario' => 'По сценарию',
  'Success is attributed to the assistant model. Runs before 1.6.3 did not separate assistant and judge, so they show as "Assistant + judge".' => 'Успех приписывают модели-помощнику. До версии 1.6.3 ассистент и судья не разделялись, поэтому они отображаются как «Ассистент + судья».',
