  'Estimated cost: ~{c}' => 'Ориентировочная стоимость: ~{c}',
  'assistant {a} + judge {j}' => 'ассистент {a}+ судья {j}',
  'Based on average token usage of {n} past scenario results; actual cost per scenario may vary.' => 'На основе среднего использования токенов {n} по результатам прошлых сценариев; фактическая стоимость каждого сценария может отличаться.',
  'No runs yet; default estimate: ~{i} input / {o} output tokens per donor message.' => 'Пробегов пока нет; оценка по умолчанию: ~ входные токены {i}/выходные токены {o} на одно сообщение донора.',
  'The estimate exceeds the cost limit; the run stops when the limit is reached.' => 'Смета превышает лимит стоимости; запуск останавливается при достижении предела.',
  'New run' => 'Новый запуск',
  'Scenarios are played like in the test chat: no WhatsApp message is sent and no record is created. The model is really called; the cost is charged to your AI account (OpenRouter or Anthropic) and the run stops when the limit is reached.' => 'Сценарии проигрываются как в тестовом чате: сообщения в WhatsApp не отправляются и записи не создаются. Модель действительно называется; стоимость взимается с вашей учетной записи AI (OpenRouter или Anthropic), и запуск останавливается при достижении лимита.',
  'Cost limit (USD)' => 'Лимит стоимости (долл. США)',
  'Past runs' => 'Прошлые запуски',
  'All chats, tool calls and judge log' => 'Все чаты, вызовы инструментов и журнал судей',
  'Report' => 'Отчет',
  'Delete this run and its results?' => 'Удалить этот запуск и его результаты?',
  'Running in the background on the server; it continues even if you close the page.' => 'Работа в фоновом режиме на сервере; оно продолжится, даже если вы закроете страницу.',
  'Watch results live' => 'Смотрите результаты в прямом эфире',
  'Download report (.md)' => 'Скачать отчет (.md)',
  'of {n} scenarios' => 'сценариев {n}',
  '{r} read, {w} written' => '{r} читается, {w} записывается.',
