  'The remaining scenarios were not counted as failed. Check the provider budget, credit or key, then use Continue to resume where it stopped.' => 'Остальные сценарии не были засчитаны как провальные. Проверьте бюджет, кредит или ключ поставщика, затем используйте «Продолжить», чтобы возобновить работу с того места, где она была остановлена.',
  'Handed off when it should' => 'Передано, когда это должно быть',
  'Correct handoff' => 'Правильная передача',
  'Did not hand off when it should not' => 'Не передал, когда не следовало',
