  'Write a scenario with AI' => 'Напишите сценарий с помощью ИИ',
  'Reset the built-in scenarios? Scenarios you added are kept.' => 'Сбросить встроенные сценарии? Добавленные вами сценарии сохраняются.',
  'Restore built-in scenarios' => 'Восстановление встроенных сценариев',
  'In messages {tur} = "{a}", {birim} = "{b}", {brand} = "{c}".' => 'В сообщениях {tur}= «{a}», {birim}= «{b}», {brand}= «{c}».',
  'Must contain' => 'Должен содержать',
