  'One phrase per line' => 'Одна фраза в строке',
  'E.g. Should not ask for a name; short and warm greeting.' => 'например Не следует спрашивать имя; короткое и теплое приветствие.',
  'One tool name per line; a|b for alternatives' => 'Одно название инструмента в строке; a|b для альтернатив',
