  'Group' => 'Группа',
  'Messages (in order)' => 'Сообщения (по порядку)',
  '{tur}, {birim} and {brand} can be used. If there are only customer messages, the assistant replies to each in turn. If you add assistant messages it becomes a continuation scenario: the written history is given as-is and the assistant replies only to the last customer message.' => 'Можно использовать {tur}, {birim} и {brand}. Если есть только сообщения клиентов, помощник отвечает на каждое по очереди. Если вы добавите сообщения помощника, это станет сценарием продолжения: записанная история предоставляется как есть, и помощник отвечает только на последнее сообщение клиента.',
  'E.g. payment_info, cancel_donation, receipt_check. Tools disabled on this site are not checked.' => 'например платежная_информация, отмена_пожертвования, чек_чека. Инструменты, отключенные на этом сайте, не проверяются.',
  'Who is writing?' => 'Кто пишет?',
  'Starting state (test)' => 'Начальное состояние (тестовое)',
  'The scenario runs isolated like the test chat; what you select here exists only in this test. In a customer message, {kod} becomes the verification code from the test panel.' => 'Сценарий выполняется изолированно, как и тестовый чат; то, что вы здесь выбираете, существует только в этом тесте. В сообщении клиента {kod} становится кодом подтверждения с тестовой панели.',
  'End state' => 'Конечное состояние',
  'When the conversation ends, the test state is checked (was a donation opened, canceled, a code sent…). Tools disabled on this site are not checked.' => 'По окончании разговора проверяется состояние теста (было ли открыто пожертвование, отменено, отправлен код...). Инструменты, отключенные на этом сайте, не проверяются.',
  'Judge criterion' => 'Критерий судьи',
  'If empty, the judge is not called. Put quality expectations that cannot be written as rules here.' => 'Если пусто, судья не вызывается. Поместите сюда ожидания от качества, которые нельзя записать в виде правил.',
  'Message written by the assistant' => 'Сообщение написал помощник',
  'Message written by the customer' => 'Сообщение, написанное клиентом',
  'Drag to reorder' => 'Перетащите, чтобы изменить порядок',
