  'Missing table: %s. Deactivate and reactivate the plugin.' => 'Отсутствует таблица: %s. Деактивируйте и повторно активируйте плагин.',
  'Tables ready (schema %s).' => 'Таблицы готовы (схема %s).',
  'Schema update pending; it completes when you open a page in the admin panel.' => 'Ожидается обновление схемы; он завершается, когда вы открываете страницу в панели администратора.',
  'Media folder' => 'Медиа-папка',
  'Cannot write to uploads/flx-chat; incoming photos, voice notes and documents cannot be saved. Check folder permissions.' => 'Не могу писать в uploads/flx-chat; входящие фотографии, голосовые заметки и документы сохранить невозможно. Проверьте права доступа к папке.',
  'Folder protection (.htaccess) missing; it is created with the first saved media.' => 'Защита папки (.htaccess) отсутствует; он создается с использованием первого сохраненного носителя.',
