  'Available.' => 'Доступен.',
  'Missing; while the assistant prepares a reply the "typing…" indicator shows only briefly.' => 'Отсутствует; пока помощник готовит ответ, индикатор «ввод...» горит лишь кратковременно.',
  'Users with the agent role: %d.' => 'Пользователи с ролью агента: %d.',
  'No user has the agent role; only administrators can use it for now.' => 'Ни один пользователь не имеет роли агента; пока только администраторы могут использовать его.',
  'Live panel updates' => 'Обновления панели в реальном времени',
  'The chat screen has not been opened yet.' => 'Экран чата еще не открыт.',
  'WhatsApp line' => 'Линия WhatsApp',
  'No line added.' => 'Ни одна строка не добавлена.',
  '%s: connection details' => '%s: сведения о подключении.',
  'Using Flux Mail connection: %s.' => 'Использование соединения Flux Mail: %s.',
  'Still using the old provider in Flux Certificates; move the connection to Flux Mail and select it here.' => 'Все еще использую старого провайдера в сертификатах Flux; переместите соединение с Flux Mail и выберите его здесь.',
  'Using the Evolution provider from Flux Certificates.' => 'Использование поставщика Evolution из сертификатов Flux.',
  'API URL, key and instance are entered in this plugin.' => 'URL-адрес API, ключ и экземпляр вводятся в этот плагин.',
  '%s: line status' => '%s: статус линии.',
  'Phone connected (last seen %s).' => 'Телефон подключен (последний раз видел %s).',
  'Not tested yet. Press "Test connection".' => 'Еще не тестировался. Нажмите «Проверить соединение».',
  'Phone not connected (state: %1$s, %2$s). Reconnect with "Connect with QR".' => 'Телефон не подключен (состояние: %1$s, %2$s). Повторно подключитесь с помощью «Подключиться с помощью QR».',
  '%s: Evolution API version' => '%s: версия API эволюции.',
  'Evolution API %s is in use. Replies to hidden-number (@lid) contacts may fail; update the server to 2.3 or later.' => 'Используется Evolution API %s. Ответы на контакты со скрытым номером (@lid) могут не получиться; обновите сервер до версии 2.3 или новее.',
  '%s: webhook (incoming messages)' => '%s: вебхук (входящие сообщения)',
  'No events have arrived from Evolution; incoming messages will not show in the panel. Press "Set up webhook".' => 'Никаких событий от «Эволюции» не поступило; входящие сообщения не будут отображаться на панели. Нажмите «Настроить вебхук».',
  'Last event arrived %s. The line may just be quiet; send yourself a message or set up the webhook again to be sure.' => 'Последнее событие прибыло %s. На линии может быть просто тихо; отправьте себе сообщение или настройте вебхук еще раз, чтобы быть уверенным.',
  'Last event arrived %s.' => 'Последнее событие прибыло %s.',
  'Flux Mail integration' => 'Интеграция Flux Mail',
  'Active: WhatsApp connections are taken from Communication › Connections.' => 'Активно: соединения WhatsApp берутся из раздела Общение › Соединения.',
  'Flux Mail is not active; connections are taken from Flux Certificates or from this plugin.' => 'Flux Mail не активен; подключения берутся из Flux Certificates или из этого плагина.',
  'Flux Certificates integration' => 'Интеграция сертификатов Flux',
  'Active: certificates can be created and sent from chats.' => 'Активно: сертификаты можно создавать и отправлять из чатов.',
  'Flux Certificates is not active; certificate actions in chats are off.' => 'Сертификаты Flux не активны; действия с сертификатами в чатах отключены.',
  'Flux Donate integration' => 'Интеграция Flux Donate',
  'Active: donation records, receipt matching and the assistant are available from chats.' => 'Активно: записи пожертвований, сопоставление квитанций и помощник доступны из чатов.',
  'Flux Donate is not active; donation records, receipt matching and the donation assistant are off.' => 'Flux Donate не активен; записи пожертвований, сопоставление квитанций и помощник по пожертвованиям отключены.',
  'The Flux AI & MCP plugin is not installed; AI features (suggestions, assistant, receipt reading, voice messages, summaries) are off. Install Flux AI and enter the key there.' => 'Плагин Flux AI & MCP не установлен; Функции искусственного интеллекта (предложения, помощник, чтение квитанций, голосовые сообщения, сводки) отключены. Установите Flux AI и введите туда ключ.',
  'No key has been entered in Flux AI; message suggestions and the assistant are off.' => 'В Flux AI не был введен ключ; предложения сообщений и помощник отключены.',
  'Key saved but no model selected.' => 'Ключ сохранен, но модель не выбрана.',
  'No provider key has been entered in Flux AI for the selected model (%s).' => 'В Flux AI для выбранной модели не был введен ключ провайдера (%s).',
  'Key saved, model: %s. Use "Test connection" for a live check.' => 'Ключ сохранен, модель: %s. Используйте «Тестовое соединение» для проверки в реальном времени.',
  'Donation assistant' => 'Помощник по пожертвованиям',
  'Off.' => 'Выкл.',
  'AI key or model is missing.' => 'Ключ или модель AI отсутствует.',
  'On but not replying: ' => 'Включаю, но не отвечаю:',
  'On. Donation types offered: %s.' => 'Вкл. Предлагаемые типы пожертвований: %s.',
  '%s does not support tools; choose a tool-capable model for the assistant.' => '%s не поддерживает инструменты; выберите для помощника модель, поддерживающую инструмент.',
  'Receipt reading model' => 'Модель чтения квитанции',
  '%s cannot read images; the receipt pre-check will not work. Choose an image-capable receipt reading model.' => '%s не может читать изображения; предварительная проверка чека не будет работать. Выберите модель чтения квитанций с возможностью изображения.',
  'Assistant payment details' => 'Платежные реквизиты помощника',
  'Recipient name and IBAN set.' => 'Имя получателя и набор IBAN.',
  'Recipient name or IBAN missing; bank details cannot be sent after confirmation.' => 'Имя получателя или IBAN отсутствуют; Банковские реквизиты не могут быть отправлены после подтверждения.',
  'Donation page link' => 'Ссылка на страницу пожертвований',
  'Donation page not found; the assistant will not send a link.' => 'Страница пожертвования не найдена; помощник не отправит ссылку.',
  'Background requests' => 'Фоновые запросы',
  'The site could not send a background request to itself (%1$s: %2$s). Queued replies and the benchmark may move slowly; a security plugin or the server firewall may be blocking /wp-json/flx-chat/ requests.' => 'Сайт не смог отправить себе фоновый запрос (%1$s: %2$s). Ответы в очереди и контрольный показатель могут двигаться медленно; плагин безопасности или брандмауэр сервера могут блокировать запросы /wp-json/flx-chat/.',
  'error' => 'ошибка',
  'warning' => 'предупреждение',
  'ok' => 'ок',
  'Your {marka} verification code: {kod}' => 'Ваш код подтверждения {marka}: {kod}.',
  'The code is valid for {dk} minutes. Type it in your WhatsApp chat with us. If you did not ask for it, ignore this message.' => 'Код действителен в течение {dk} минут. Введите его в свой чат WhatsApp с нами. Если вы не просили об этом, проигнорируйте это сообщение.',
  'Something went wrong; our team will contact you as soon as possible 🌱 Meanwhile, feel free to ask anything else.' => 'Что-то пошло не так; наша команда свяжется с вами как можно скорее 🌱 А пока не стесняйтесь спрашивать что-нибудь еще.',
  'Verification attempt failed (%1$d/%2$d): %3$s' => 'Попытка проверки не удалась (%1$d/%2$d): %3$s.',
  'The person wanted to see their records but could not be verified; someone from the team should get in touch' => 'Человек хотел просмотреть свои записи, но его не удалось проверить; кто-то из команды должен связаться',
  'e-mail could not be sent (check Flux Mail › SMTP settings)' => 'Не удалось отправить электронное письмо (проверьте Flux Mail › настройки SMTP)',
  'The assistant sent a verification code for %1$s (%2$s).' => 'Ассистент отправил код подтверждения для %1$s(%2$s).',
  'code expired' => 'срок действия кода истек',
  'wrong code' => 'неправильный код',
  'The person verified the code for %s; it is added to their record lookups.' => 'Человек проверил код %s; он добавляется в их поиск по записям.',
  'Claude models cannot read audio; choose an audio-capable OpenRouter model in Settings › AI › Voice message model.' => 'Модели Claude не могут читать аудио; выберите модель OpenRouter с поддержкой аудио в меню «Настройки» > «AI» > «Модель голосового сообщения».',
  'The audio could not be transcribed.' => 'Звук не удалось расшифровать.',
  'The audio file could not be read.' => 'Аудиофайл не может быть прочитан.',
  'Voice message (%1$s) transcribed: %2$s' => 'Голосовое сообщение (%1$s) расшифровано: %2$s',
  'Voice message (%1$s) could not be processed: %2$s' => 'Голосовое сообщение (%1$s) не удалось обработать: %2$s.',
  'This action is not available on an official WhatsApp Cloud API line.' => 'Это действие недоступно в официальной строке WhatsApp Cloud API.',
  'WhatsApp 24-hour rule: the contact has not written in the last 24 hours, so the Cloud API will not send a free-form message; only an approved template can be sent. Try again once they write.' => 'Правило 24 часов в WhatsApp: контакт не писал в течение последних 24 часов, поэтому Cloud API не будет отправлять сообщение в свободной форме; можно отправить только утвержденный шаблон. Попробуйте еще раз, как напишут.',
  'A Cloud API line needs Flux Mail 1.10.0 or later.' => 'Для линии Cloud API требуется Flux Mail 1.10.0 или новее.',
  'The Cloud API cannot send to this address (hidden number or group).' => 'Cloud API не может отправить сообщение на этот адрес (скрытый номер или группу).',
  'Could not reach the Cloud API account (İletişim › Connections).' => 'Не удалось получить доступ к учетной записи Cloud API (İletişim › Connections).',
  'A Cloud API line has no QR code; the account is set up in İletişim › Connections.' => 'Линия Cloud API не имеет QR-кода; учетная запись настроена в İletişim › Connections.',
  'The file could not be prepared.' => 'Не удалось подготовить файл.',
  'Flux AI has no image support.' => 'Flux AI не поддерживает изображения.',
  'The image could not be rendered.' => 'Изображение не удалось отобразить.',
  'The assistant\'s image could not be sent: ' => 'Не удалось отправить изображение помощника:',
  'Hello {first_name}, we have created your donation record: {donation}, total {amount}.' . chr(10) . '' . chr(10) . '{bank}' . chr(10) . '' . chr(10) . 'After paying, you can send the receipt here. Thank you.' => 'Здравствуйте, {first_name}, мы создали запись о вашем пожертвовании: {donation}, общая сумма {amount}.{bank} После оплаты вы можете отправить чек сюда. Спасибо.',
  'Hello {first_name}, your donation has been recorded: {donation}, total {amount}.' . chr(10) . '' . chr(10) . 'Thank you for your support.' => 'Здравствуйте, {first_name}, ваше пожертвование зарегистрировано: {donation}, общая сумма {amount}.' . chr(10) . '' . chr(10) . 'Спасибо за вашу поддержку.',
  'The plugin that would run this scenario is inactive.' => 'Плагин, который будет запускать этот сценарий, неактивен.',
  'This user is not allowed to use the staff tools.' => 'Этому пользователю не разрешено использовать штатные инструменты.',
  '%1$s linked this chat to staff member %2$s' => '%1$s связал этот чат с сотрудником %2$s',
  '%s removed the staff link of this chat' => '%s удалил ссылку на персонал этого чата.',
  'Chat linked to staff member' => 'Чат связан с сотрудником',
  'Staff link removed' => 'Ссылка на персонал удалена',
  '— Not staff —' => '— Не персонал —',
  'WhatsApp hides this person\'s number, so the assistant cannot recognise staff by number. If this person is on your team, link them here and the assistant opens the staff tools.' => 'WhatsApp скрывает номер этого человека, поэтому помощник не может распознать сотрудника по номеру. Если этот человек входит в вашу команду, свяжите его здесь, и помощник откроет инструменты для персонала.',
  'The assistant recognises staff by the number in their Flux Roles profile. If the number does not match, you can link them here; in a chat with a known number the number comes first.' => 'Ассистент узнает сотрудников по номеру в их профиле ролей Flux. Если номера не совпадают, вы можете связать их здесь; в чате с известным номером номер стоит первым.',
  'This channel is not available right now.' => 'Этот канал сейчас недоступен.',
  'Site chat' => 'Чат на сайте',
  'All messages from WhatsApp, site chat and other channels appear here live. Pick a chat on the left.' => 'Все сообщения из WhatsApp, чата сайта и других каналов отображаются здесь в прямом эфире. Выберите чат слева.',
  '[[\'WhatsApp (Evolution API) call center: see live incoming and outgoing messages, start new chat, canned replies, tags, assignment, internal notes, auto-replies; Donation (Flux Donate) and certificate (Flux Certificates) registration from chat, receipt matching. Artificial intelligence response suggestion and automatic donation assistant with OpenRouter.\', \'tr\']]' => 'Колл-центр WhatsApp (Evolution API): просмотр входящих и исходящих сообщений в реальном времени, запуск нового чата, готовые ответы, теги, назначения, внутренние заметки, автоответы; Регистрация пожертвований (Flux Donate) и сертификатов (Flux Certificates) из чата, сопоставление квитанций. Предложение ответа искусственного интеллекта и автоматический помощник по пожертвованиям с OpenRouter.',
  'Çağrı Merkezi' => 'Колл-центр',
  'Sohbetler' => 'Чаты',
  'AI asistan' => 'ИИ-помощник',
  'Çağrı Merkezi Ayarları' => 'Настройки колл-центра',
  'Ayarlar' => 'Настройки',
  'Çağrı Merkezi için JavaScript gerekli.' => 'Для работы колл-центра требуется JavaScript.',
  'Bu sayfaya erişim yetkiniz yok.' => 'У вас нет разрешения на доступ к этой странице.',
  'Asistanın yazıştığı sohbetleri izleyin, talimatını ve belgelerini düzenleyin, değişiklikleri yayına almadan önce test edin.' => 'Контролируйте чаты, которые ведет помощник, редактируйте его инструкции и документы, а также тестируйте изменения перед их публикацией.',
  'Asistan ayarları' => 'Настройки Ассистента',
  'Bu sayfa için JavaScript gerekli.' => 'Для этой страницы требуется JavaScript.',
  'Kapalı' => 'Закрыто',
  'Açık, 5 dakika' => 'Включено, 5 минут',
  'Açık, 1 saat' => 'Включено, 1 час',
  'Yapay zekâ için Flux AI & MCP eklentisi gerekli; kurup etkinleştirin ve Flux AI & MCP › Ayarlar\'a anahtarı girin.' => 'ИИ нужен плагин Flux AI & MCP; установите и активируйте его, затем введите ключ в Flux AI & MCP › Настройки.',
  'Yapay zekâ modeli seçilmemiş.' => 'Модель ИИ не выбрана.',
  'Flux AI\'de Anthropic (Claude) anahtarı girilmemiş.' => 'В Flux AI не был введен ключ Anthropic (Claude).',
  'Flux AI\'de OpenRouter anahtarı girilmemiş.' => 'В Flux AI не был введен ключ OpenRouter.',
  'Model listesi için Flux AI & MCP eklentisi gerekli.' => 'Для списка моделей требуется плагин Flux AI & MCP.',
  'Flux Chat: yapay zekâ özellikleri (öneri, asistan, dekont okuma, sesli mesaj, özet) için Flux AI & MCP eklentisi gerekli. Kurup etkinleştirin; Çağrı Merkezi\'nde kayıtlı anahtarlar oraya kendiliğinden aktarılır.' => 'Колл-центр Flux: для функций искусственного интеллекта (предложения, помощник, чтение квитанций, голосовые сообщения, сводки) требуется плагин Flux AI & MCP. Установите и активируйте его; ключи, сохраненные в колл-центре, перемещаются туда автоматически.',
  'Flux Chat: %s anahtarı Flux AI\'de farklı bir anahtar olarak zaten kayıtlı; Flux AI\'deki kullanılıyor. Çağrı Merkezi\'ndeki eski anahtar aktarılmadı ve artık kullanılmıyor.' => 'Колл-центр Flux: другой ключ %s уже сохранен в Flux AI и используется именно он. Старый ключ колл-центра не был перемещен и больше не используется.',
  'Flux Chat: yapay zekâ anahtarları Flux AI\'ye aktarıldı. Bundan sonra anahtar, harcama sınırı ve kayıtlar Flux AI\'den yönetilir; model seçimleri Çağrı Merkezi\'nde kalır.' => 'Колл-центр Flux: ключи AI были перенесены в Flux AI. Отныне ключи, лимиты расходов и журналы управляются в Flux AI; выбор модели остается в колл-центре.',
  'Flux Donate eklentisi etkin değil; asistan bağış türlerini ve fiyatları oradan alır.' => 'Плагин Flux Donate не активен; из него помощник берет виды пожертвований и цены.',
  'Flux Donate\'ta açık bağış türü yok (Bağış türleri sayfasından bir türü açın).' => 'В Flux Donate нет открытого типа пожертвования (откройте его на странице «Типы пожертвований»).',
  'Asistan için seçilen bağış türleri kapalı ya da fiyatsız; açık bir tür seçin ya da seçimi boş bırakın.' => 'Выбранные для помощника виды пожертвований являются закрытыми или не имеют цены; выберите открытый тип или оставьте выбор пустым.',
  'Açık bağış türlerinin hiçbirinde fiyat yok (Flux Donate › Bağış türleri › seçenek fiyatı).' => 'Ни один из видов открытого пожертвования не имеет цены (Flux Donate › Виды пожертвований › Цена опциона).',
