  'Dekontunuzu aldık, teşekkür ederiz 🌱 Ödemenizle ilgili size en kısa zamanda dönüş yapacağız.' => 'Мы получили вашу квитанцию, спасибо 🌱 Мы свяжемся с вами по поводу оплаты как можно скорее.',
  'Dekontunuzu aldık, teşekkür ederiz 🌱 Bağışınız onaylandı.' => 'Мы получили вашу квитанцию, спасибо 🌱 Ваше пожертвование подтверждено.',
  'Bu dekontu daha önce almıştık, teşekkür ederiz 🌱 Ödemenizle ilgili size en kısa zamanda dönüş yapacağız.' => 'Мы уже получили эту квитанцию, спасибо 🌱 Мы свяжемся с вами по поводу оплаты как можно скорее.',
  'Bu dekont daha önce sistemimize yüklenmiş görünüyor. Aynı dekont ikinci bir bağış için kullanılamaz. Farklı bir ödeme yaptıysanız o ödemenin dekontunu gönderebilirsiniz; ekibimiz de ayrıca kontrol edecek.' => 'Похоже, эта квитанция уже была загружена в нашу систему ранее. Эту же квитанцию ​​нельзя использовать для второго пожертвования. Если вы произвели другой платеж, отправьте эту квитанцию; наша команда также проверит.',
  'Dekontunuzu aldık. Dekonttaki tutar (%1$s) bağışınızın tutarıyla (%2$s) uyuşmuyor gibi görünüyor. Kontrol edebilir misiniz? Farklı bir ödeme yaptıysanız buradan yazabilirsiniz, ekibimiz de ayrıca bakacak.' => 'Мы получили вашу квитанцию. Сумма на нем (%1$s), похоже, не соответствует сумме вашего пожертвования (%2$s). Не могли бы вы это проверить? Если вы произвели другой платеж, вы можете написать здесь; наша команда также рассмотрит.',
  'Dekontunuzu aldık, ancak dekonttaki alıcı derneğimiz değil gibi görünüyor. Bağışlarımız yalnız "%s" adına açılmış hesabımıza yapılır. Kontrol edebilir misiniz? Ekibimiz de ayrıca bakacak.' => 'Мы получили вашу квитанцию, но получатель на ней, похоже, не является нашей ассоциацией. Пожертвования переводятся на наш счет только на имя «%s». Не могли бы вы проверить? Наша команда тоже присмотрится.',
  'Dekontunuzu aldık, ancak dekonttaki alıcı bilgisi bizim hesabımızla eşleşmiyor gibi görünüyor. Kontrol edebilir misiniz? Ekibimiz de ayrıca bakacak.' => 'Мы получили вашу квитанцию, но получатель на ней, похоже, не соответствует нашему аккаунту. Не могли бы вы проверить? Наша команда тоже присмотрится.',
  'Gönderdiğiniz dosya bir ödeme dekontuna benzemiyor. Ödemeyi yaptıysanız dekontu ya da ödeme ekranının görüntüsünü buradan gönderebilirsiniz.' => 'Отправленный вами файл не похож на квитанцию об оплате. Если вы произвели оплату, вы можете отправить сюда квитанцию ​​или скриншот экрана оплаты.',
