  '+ Yeni rapor' => '+ Новый отчет',
  'Alıcının numarası Kullanıcılar › Profil › WhatsApp numarası alanından gelir; yetkiler Kullanıcılar › Roller ve erişim sayfasından (rapor alabilir, genel raporu görebilir, raporları yönetir). Rapor seçilen saatte gider; sunucu zamanlayıcısı yoksa sitenin ilk ziyaretinde ya da sohbet panelinde gönderilir.' => 'Номер получателя берется из Пользователи › Профиль › Номер WhatsApp; разрешения пользователей › Роли и доступ (получение отчетов, просмотр общего отчета, управление отчетами). Отчеты выходят в выбранное время; без планировщика сервера они отправляются при следующем посещении сайта или использовании панели чата.',
