  'Bu kişi kara listede; mesaj gönderilmez. Kara listeden çıkarınca yeniden yazabilirsiniz.' => 'Этот контакт занесен в черный список; никакие сообщения не отправляются. Удалите их из черного списка, чтобы написать снова.',
  'Mesaj kaydedilemedi.' => 'Сообщение не удалось сохранить.',
  'Bu kişi WhatsApp gizli numarasıyla (@lid) yazıyor ve Evolution API (sürüm %s) bu adrese gönderemedi. Evolution API sunucusunu 2.3 veya üstüne güncelleyin; kişinin gerçek numarası gelirse eklenti oraya gönderir.' => 'Этот контакт пишет со скрытого номера WhatsApp (@lid) и Evolution API (версия %s) не смог отправить на этот адрес. Обновите сервер Evolution API до версии 2.3 или новее; если приходит реальный номер контакта, плагин отправляет туда.',
  'Bu kişi WhatsApp gizli numarasıyla (@lid) yazıyor ve Evolution API bu adrese gönderemedi. Evolution API sunucusunu 2.3 veya üstüne güncelleyin; kişinin gerçek numarası gelirse eklenti oraya gönderir.' => 'Этот контакт пишет со скрытого номера WhatsApp (@lid), и Evolution API не смог отправить сообщение на этот адрес. Обновите сервер Evolution API до версии 2.3 или новее; если приходит реальный номер контакта, плагин отправляет туда.',
  'WhatsApp bağlantısı yok.' => 'Нет подключения к WhatsApp.',
  'Bağlı ✓' => 'Подключено ✓',
  'Bağlı değil (durum: %s). QR ile bağlayın.' => 'Не подключено (состояние: %s). Подключитесь с помощью QR.',
  'Webhook bu siteye ayarlı ✓' => 'Webhook указывает на этот сайт ✓',
  'Evolution API sürümü: %s' => 'Версия API эволюции: %s.',
  '(eski: gizli numaralı (@lid) kişilere cevap gidemeyebilir, 2.3 veya üstüne güncelleyin)' => '(старая версия: ответы на контакты со скрытым номером (@lid) могут не получиться, обновите до версии 2.3 или более поздней)',
  'Webhook bu siteye ayarlı değil. "Webhook\'u kur" düğmesine basın.' => 'Вебхук не направлен на этот сайт. Нажмите «Настроить вебхук».',
  'Webhook kuruldu ✓ Artık gelen mesajlar buraya düşer.' => 'Настройка вебхука ✓ Теперь входящие сообщения будут поступать сюда.',
  'Son sohbetler içe aktarılıyor, bu biraz sürebilir…' => 'Импорт последних чатов. Это может занять некоторое время...',
  'Evolution\'da kayıtlı mesaj: %s' => 'Сообщения, хранящиеся в Evolution: %s',
  'Evolution mesajları kaydetmiyor, bu yüzden eski mesajlar gelemez. Evolution sunucusunda DATABASE_SAVE_DATA_NEW_MESSAGE ve DATABASE_SAVE_DATA_HISTORIC değerlerini true yapın; eski konuşmalar için hattı QR ile yeniden bağlarken instance ayarında "Sync full history" açık olsun.' => 'Evolution не хранит сообщения, поэтому старые сообщения загрузить невозможно. На сервере Evolution установите для DATABASE_SAVE_DATA_NEW_MESSAGE и DATABASE_SAVE_DATA_HISTORIC значение true; для более старых разговоров оставьте включенным параметр «Синхронизировать полную историю» в настройках экземпляра при повторном подключении линии с помощью QR.',
  '%1$s sohbet, %2$s mesaj içe aktarıldı ✓' => 'Импортированы чаты %1$s, сообщения %2$s✓',
  'WhatsApp › Bağlı cihazlar › Cihaz bağla ile bu kodu okutun.' => 'Отсканируйте этот код через WhatsApp › Связанные устройства › Привяжите устройство.',
  'Eşleştirme kodu:' => 'Код сопряжения:',
