  'WhatsApp hattınızı bağlayın, otomatik yanıtları ve etiketleri yönetin.' => 'Подключите свою линию WhatsApp, управляйте автоответами и метками.',
  'Sohbetleri aç' => 'Открытые чаты',
  'Ayarlar kaydedildi.' => 'Настройки сохранены.',
  'Çağrı Merkezi\'nin çalışması için gereken bağlantılar ve ayarlar. Kayıtlı durumlar gösterilir; canlı deneme için ilgili sekmedeki "test et" düğmelerini kullanın. Aynı kontroller temanın sistem kontrolü ekranında diğer eklentilerle birlikte de görünür.' => 'Соединения и настройки, необходимые колл-центру. Отображается сохраненный статус; используйте кнопки «тест» на каждой вкладке для проверки в реальном времени. Те же проверки отображаются и с другими плагинами на экране проверки системы темы.',
  'WhatsApp hatları' => 'Линии WhatsApp',
  'Mesajlar Evolution API üzerinden gönderilir ve alınır. WhatsApp bağlantıları Flux Mail\'de yönetilir; burada hangisinin kullanılacağını seçin. Adres ve API key orada kalır, değişince burada ayrıca güncellemek gerekmez.' => 'Сообщения отправляются и принимаются через Evolution API. Подключения WhatsApp управляются в Flux Mail; выберите, какой из них использовать здесь. URL-адрес и ключ API остаются там, поэтому вам не нужно обновлять их здесь при их изменении.',
  'İletişim › Bağlantılar' => 'Связь › Соединения',
  'Mesajlar Evolution API üzerinden gönderilir ve alınır. Flux Certificates eklentisinde Evolution sağlayıcısı tanımlıysa aynı bağlantıyı seçebilirsiniz; adres ve API key orada kalır.' => 'Сообщения отправляются и принимаются через Evolution API. Если провайдер Evolution настроен в сертификатах Flux, вы можете выбрать то же соединение; URL-адрес и ключ API остаются там.',
  'Hat ekle' => 'Добавить строку',
  'Kurulum adımları' => 'Шаги настройки',
  'Hattı ekleyip kaydedin.' => 'Добавьте строку и сохраните.',
  '"Bağlantıyı test et" ile Evolution\'a ulaşıldığını görün. Hat bağlı değilse "QR ile bağla" deyip telefondan okutun.' => 'Используйте «Проверочное соединение», чтобы убедиться, что Evolution доступен. Если линия не связана, выберите «Подключиться с помощью QR» и отсканируйте ее с телефона.',
  '"Webhook\'u kur" düğmesine basın. Gelen mesajlar, telefondan ve Flux Certificates\'dan gönderilenler canlı olarak buraya düşer.' => 'Нажмите «Настроить вебхук». Входящие сообщения и сообщения, отправленные с телефона и из сертификатов Flux, затем появляются здесь в прямом эфире.',
  'İsterseniz "Son sohbetleri içe aktar" ile geçmiş mesajları getirin.' => 'При желании можно добавить прошлые сообщения с помощью «Импортировать последние чаты».',
