  'Medya dosyaları wp-content/uploads/flx-chat klasöründe, dışarıdan erişime kapalı tutulur. Site taşınırken uploads ile birlikte gider.' => 'Медиа-файлы хранятся в папке wp-content/uploads/flx-chat и закрыты для внешнего доступа. Они перемещаются вместе с загрузками при переносе сайта.',
