  'Sohbet etiketleri' => 'Chat labels',
  'Sohbetleri etiketleyip listede filtreleyin (ör. Bağış, Şikâyet, Takip).' => 'Пометьте чаты и отфильтруйте список (например, «Пожертвование», «Жалоба», «Последующие действия»).',
