  'Sohbetten kayıt oluşturma' => 'Создание записей из чатов',
  'Sohbet başlığındaki düğmelerle bağış kaydı (Flux Donate) ve sertifika (Flux Certificates) oluşturulur, gelen dekont kayıtla eşleştirilir. Eklenti kurulu değilse ilgili düğme görünmez.' => 'Кнопки в шапке чата создают запись о пожертвовании (Flux Donate) и сертификат (Flux Certificates), а входящая квитанция сопоставляется с записью. Если плагин не установлен, его кнопка скрыта.',
  'Temsilciler bağış kaydı oluşturabilsin ve dekont eşleştirebilsin' => 'Агенты могут создавать записи о пожертвованиях и сопоставлять квитанции.',
