  'Dekont onaylandı' => 'Получение подтверждено',
  'Banka bilgisi ({bank})' => 'Банковские реквизиты ({bank})',
  'Alıcı adı, banka, IBAN' => 'Имя получателя, банк, IBAN',
  'Boşsa WooCommerce › Ödemeler › Havale / EFT ayarındaki hesap kullanılır.' => 'Если пусто, используется учетная запись в WooCommerce › Платежи › Банковский перевод.',
  'Değişkenler: {first_name}, {name}, {donation}, {amount}, {quantity}, {bank}, {certificate_link}, {agent}, {brand}, {date}.' => 'Переменные: {first_name}, {name}, {donation}, {amount}, {quantity}, {bank}, {certificate_link}, {agent}, {brand}, {date}.',
  'Yapay zekâ bağlantısı' => 'AI-соединение',
  'Anahtarlar, prompt önbelleği, harcama sınırı ve kullanım kayıtları Flux AI & MCP eklentisinden gelir; Çağrı Merkezi\'nin tüm yapay zekâ istekleri oradan geçer. Model seçimleri burada kalır; alanlar boşsa Flux AI\'de bu eklentiye seçilen model (ya da varsayılan) kullanılır.' => 'Ключи, оперативное кэширование, лимиты расходов и журналы использования поступают из плагина Flux AI & MCP; все запросы ИИ колл-центра проходят через него. Выбор модели остается здесь; если поле пусто, используется модель, выбранная для этого плагина в Flux AI (или модель по умолчанию).',
  'Flux AI ayarlarını aç' => 'Откройте настройки Flux AI.',
  'Yapay zekâ için Flux AI & MCP eklentisi gerekli. Kurup etkinleştirin ve Flux AI & MCP › Ayarlar\'a OpenRouter ve/veya Anthropic anahtarını girin. O zamana kadar öneri, asistan, dekont okuma, sesli mesaj ve özet kapalıdır.' => 'ИИ нужен плагин Flux AI & MCP. Установите и активируйте его, затем введите ключ OpenRouter и/или Anthropic в Flux AI & MCP › Настройки. До этого момента предложения, помощник, чтение квитанций, голосовые сообщения и сводки отключены.',
  'Yaratıcılık (0–1)' => 'Креативность (0–1)',
  'Düşük değer daha tutarlı, yüksek değer daha serbest cevap verir. Önerilen 0,4.' => 'Более низкие значения дают более последовательные ответы, более высокие — более свободные. рекомендуется 0,4.',
  'Model (öneriler için)' => 'Модель (для предложений)',
  'Asistan modeli (isteğe bağlı)' => 'Модель помощника (опционально)',
  'Yukarıdaki model' => 'Модель выше',
  'Yalnız araç (tools) destekleyen modeller listelenir.' => 'В списке указаны только модели, поддерживающие инструменты.',
  'Dekont okuma modeli (isteğe bağlı)' => 'Модель чтения квитанции (опционально)',
  'Seçilen model görsel okuyamıyorsa görsel okuyan ucuz bir modele kendiliğinden geçilir.' => 'Если выбранная модель не может читать изображения, автоматически используется дешевая модель зрения.',
  'Bu ay (%1$s): %2$s istek, %3$s token, yaklaşık $%4$s.' => 'В этом месяце (%1$s): запросы %2$s, токены %3$s, около $%4$s.',
  'Cevap önerisi' => 'Ответить на предложения',
  'Mesaj kutusunun üstünde, konuşmaya göre sıradaki mesaj önerilir. Temsilci "Gönder" der ya da "Düzenle" ile kutuya alıp değiştirir. Öneri asla kendiliğinden gönderilmez.' => 'Над окном сообщения предлагается следующее сообщение из беседы. Агент нажимает «Отправить» или переносит в поле «Редактировать». Предложение никогда не отправляется само по себе.',
  'Son mesaj kişiden geldiyse öneri kendiliğinden hazırlansın (kapalıysa ✨ düğmesiyle istenir)' => 'Подготовьте предложение автоматически, когда пришло последнее сообщение от человека (если выключено, спросите кнопкой ✨)',
  'Kurum bilgisi ve üslup' => 'Информация об организации и тон',
  'Ör. Derneğimiz İstanbul\'da fidan dikimi yapar. Dikimler her yıl Kasım–Mart arasında yapılır. Sertifika bağıştan sonra WhatsApp\'tan gönderilir. Samimi ama resmi bir dil kullan.' => 'например Наша ассоциация сажает саженцы в Стамбуле. Посадка производится каждый год в период с ноября по март. Сертификат отправляется на WhatsApp после пожертвования. Используйте теплый, но формальный тон.',
  'Öneri ve asistan bu bilgileri kullanır. Bağış türleri, fiyatlar, banka bilgisi ve hazır cevaplar ayrıca otomatik eklenir.' => 'Предложения и помощник используют это. Типы пожертвований, цены, банковские реквизиты и быстрые ответы добавляются автоматически.',
  'Öneri sağlayıcısı' => 'Поставщик предложений',
  'Bağış asistanı (otomatik cevap)' => 'Помощник по пожертвованиям (автоматические ответы)',
  'Açıkken asistan gelen mesajlara kendisi cevap verir: karşılar, hitap için adını sorar, bağış seçeneklerini ve fiyatları gönderir, isteğe bağlı e-posta ve "kimin adına" bilgilerini alır, her değişiklikte özet gösterip onay ister. Onaydan sonra Flux Donate\'ta "ödeme bekleniyor" kaydı açar ve bağış linki ile alıcı adı, IBAN, açıklamayı ayrı mesajlar hâlinde gönderir. Konu bağış dışına çıkarsa sohbeti ekibe devreder.' => 'При включении помощник отвечает сам: приветствует, спрашивает имя для обращения, отправляет варианты пожертвований и цены, при необходимости собирает электронную почту и «от чьего имени» и запрашивает подтверждение после каждого изменения. После подтверждения он открывает запись «ожидает платежа» в Flux Donate и отправляет ссылку для пожертвования, получателя, IBAN и ссылку в виде отдельных сообщений. Если тема оставляет пожертвования, она передает чат команде.',
  'Flux Donate eklentisi etkin değil; asistan bağış kaydı açamaz.' => 'Плагин Flux Donate не активен; помощник не может создавать записи о пожертвованиях.',
  'Talimat, belgeler, AI sohbetleri ve test sohbeti' => 'Инструкции, документы, AI-чаты и тестовый чат',
  'Bağış asistanını aç (tümünü kapatmak için işareti kaldırın)' => 'Включите помощника по пожертвованиям (снимите галочку, чтобы отключить его везде)',
  'Hangi sohbetlerde cevap versin' => 'В каких чатах он должен отвечать',
  'Tüm sohbetlerde (önerilen)' => 'Во всех чатах (рекомендуется)',
  'Temsilciye atanmamış sohbetlerde' => 'В чатах, не закрепленных за агентом',
  'Yalnız mesai saatleri dışında' => 'Только вне рабочего времени',
  'Bir temsilci sohbete yazdığında (panelden ya da telefondan) asistan o sohbette aşağıdaki süre kadar susar. Sohbet başlığındaki asistan düğmesiyle sohbet bazında açılıp kapatılır.' => 'Когда агент пишет в чат (с панели или телефона), ассистент молчит там указанное ниже время. Используйте кнопку помощника в заголовке чата, чтобы включить или выключить его для каждого чата.',
  'Test modu: yalnız aşağıdaki numaralarda cevap ver' => 'Тестовый режим: отвечайте только на номера ниже',
  'Test numaraları' => 'Номера тестов',
  'Virgül ya da satır ile ayırın. Test modu kapalıyken kullanılmaz.' => 'Разделяйте запятыми или новыми строками. Не используется, если тестовый режим выключен.',
  'Temsilci yazınca susma (saat)' => 'Тишина после того, как агент напишет (часы)',
  'Fiyat listesindeki adetler' => 'Количество в прайс-листе',
  'Konuşma geçmişi (saat)' => 'История разговоров (часы)',
  'Asistan cevaptan önce bu süredeki tüm mesajları okur.' => 'Прежде чем ответить, помощник читает все сообщения за этот период.',
  'Asistanın sunduğu bağış türleri' => 'Виды пожертвований, которые предлагает помощник',
  'Hiçbiri seçilmezse açık olan tüm türler sunulur. Yeni tür Flux Donate\'ta açıldığında asistan onu da bilir.' => 'Если ничего не выбрано, предлагаются все открытые типы. Когда в Flux Donate открывается новый тип, помощник тоже об этом узнает.',
  'Dekont ön kontrolü: kişi dekont gönderince yapay zekâ tutarı, alıcıyı ve IBAN\'ı bağışla karşılaştırır, sonucu kişiye söyler, dosyayı bağış kaydına ekler ve son onay için sohbeti ekibe devreder (ödendi işaretlemez)' => 'Предварительная проверка квитанции: когда контакт отправляет квитанцию, AI сравнивает сумму, получателя и IBAN с пожертвованием, сообщает контакту результат, прикрепляет файл к записи о пожертвовании и передает чат команде для окончательного утверждения (не помечает его как оплаченного)',
  'Fiyat listesinin son satırı' => 'Последняя строка прайс-листа',
  'Ödeme bilgileri' => 'Детали оплаты',
  'Alıcı adı ve IBAN boşsa WooCommerce › Ödemeler › Havale / EFT ayarındakiler kullanılır (siparişlerde görünen hesap). Yalnız asistan için farklı hesap istiyorsanız doldurun.' => 'Если получатель и IBAN пусты, используются те, которые указаны в WooCommerce › Платежи › Банковский перевод (счет, указанный в заказах). Заполняйте их только в том случае, если помощник должен использовать другую учетную запись.',
  'Alıcı adı' => 'Имя получателя',
  'Havale açıklaması' => 'Описание трансфера',
  'Değişkenler: {type}, {name}, {amount}, {quantity}' => 'Переменные: {type}, {name}, {amount}, {quantity}.',
  'Bağış sayfası adresi' => 'URL страницы пожертвований',
  'Linke seçilen tür ve adet eklenir (?flxb_opt=…&flxb_qty=…).' => 'Выбранный тип и количество добавляются в ссылку (?flxb_opt=...&flxb_qty=...).',
  'Ödeme bilgilerinden sonraki mesaj' => 'Сообщение после платежных реквизитов',
  'Bağış iptali onay sorusu' => 'Вопрос об отмене пожертвования',
  'Asistan yalnız ödenmemiş bağışları, kişinin onayıyla iptal eder. Boşsa varsayılan metin. Değişkenler: {bagis}, {tutar}.' => 'Помощник отменяет только неоплаченные пожертвования с согласия человека. Пусто = текст по умолчанию. Переменные: {bagis}, {tutar}.',
  'Günlük sınır dolunca gönderilen mesaj' => 'Сообщение отправляется при достижении дневного лимита',
  'Sohbet o günkü cevap sınırına ulaşınca bir kez gider, sohbet ekibe devredilir. Sınır sohbetin ⋮ menüsü › Asistan kullanımı ekranından sıfırlanır.' => 'Отправляется один раз, когда в чате достигнут дневной лимит ответов; чат передается команде. Сбросьте его из меню ⋮ чата › Использование Ассистента.',
  'Ekibe devrederken gönderilen mesaj' => 'Сообщение, отправленное при передаче команде',
  'Asistan cevap veremezse giden mesaj' => 'Сообщение отправляется, когда помощник не может ответить',
  'Yapay zekâ hata verir, süre aşılır ya da yoğunlukta sıra çok uzarsa kişiye bu mesaj gider ve sohbet ekibe devredilir; kişi hiçbir durumda cevapsız kalmaz.' => 'Если ИИ дает сбой, истекает лимит времени или очередь становится слишком длинной, это сообщение отправляется, и чат передается команде; человек никогда не остается без ответа.',
  'Bekleme mesajından önce en az (sn)' => 'Минимальное ожидание перед сообщением(ями) об удержании',
  'Kişinin mesajından bu kadar saniye geçmeden bekleme mesajı gitmez; bu arada asistan yeniden dener.' => 'Сообщение об удержании не отправляется до истечения этого количества секунд после сообщения человека; тем временем помощник повторяет попытку.',
  'Bir cevabın en uzun süresi (sn)' => 'Самое долгое время для одного ответа(ов)',
  'Hostinger istekleri ~60 sn\'de kesebilir; 50 önerilir.' => 'Hostinger может обрезать запросы примерно за 60 с; рекомендуется 50.',
  'Devirde bildirim gidecek numaralar' => 'Номера уведомлены о передаче',
  'Asistan bir sohbeti ekibe devredince bu numaralara aynı hattan WhatsApp mesajı gider: kişinin adı, telefonu, nedeni, son mesajları ve panel linki. Virgül ya da satır ile ayırın. Bu numaralarla asistan konuşmaz.' => 'Когда ассистент передает чат команде, на эти номера с одной линии отправляется сообщение WhatsApp: имя контакта, телефон, причина, последние сообщения и ссылка на панель. Разделяйте запятыми или новыми строками. Ассистент не разговаривает по этим номерам.',
  'Kişi bunlardan birini yazınca asistan beklemeden yukarıdaki devir mesajını gönderir ve o sohbette kapanır. Boş bırakılırsa örnekteki liste kullanılır.' => 'Когда контакт пишет одно из них, помощник немедленно отправляет сообщение о переключении связи, указанное выше, и отключается в этом чате. Если оставить пустым, используется список примеров.',
  'Asistana ek talimatlar' => 'Дополнительные инструкции для помощника',
  'Ör. Fidanların dikileceği yer: Kocaeli. Sertifikalar bağış onaylanınca gönderilir.' => 'например Саженцы посажены в Коджаэли. Сертификаты высылаются после подтверждения пожертвования.',
  'Kişi mesaj istemeyince gönderilen son mesaj' => 'Последнее сообщение, когда контакт отказывается от подписки',
  'Kişi "bana mesaj atmayın" gibi bir şey yazınca asistan bu mesajı gönderir ve kişiyi kara listeye alır. Kara listedeki kişiye WhatsApp, e-posta ve SMS gitmez; listeyi Sohbetler › ☰ › Kara liste\'den yönetirsiniz.' => 'Если кто-то напишет что-то вроде «не писать мне», помощник отправит это сообщение и занесет его в черный список. Человек, занесенный в черный список, не получает WhatsApp, электронной почты или SMS; управляйте списком в разделе «Чаты» › ☰ › Черный список.',
  'Kişi hafızası ve arka plan işleri' => 'Память контактов и фоновые задания',
  'Kişi hafızası: asistan kişinin kalıcı bilgilerini (hitap, yakınlarının adı, numaralar, tercihler) hatırlar; süresi dolan sohbetler özetlenir' => 'Контактная память: ассистент запоминает устойчивые детали (форму обращения, имена родственников, номера телефонов, предпочтения); просроченные чаты суммируются',
  'Sohbet kaç saat sessiz kalınca özetlensin' => 'Подведите итоги чата после того, как в нем было тихо в течение (часов)',
  'Aynı anda en fazla iş' => 'Максимальное количество рабочих мест одновременно',
  'Aynı anda cevap yazılabilecek kişi sayısı. Asistan cevapları her zaman önce gelir; cevap yazılan ya da sırada bekleyen kişi varken özet başlamaz. Her iş bir PHP işçisi kullanır: paylaşımlı hostingde sitelerin toplam işçi sınırının yarısını geçmeyin (ör. 60 işçide 20-30).' => 'Скольким людям можно ответить одновременно. Ответы Ассистента всегда на первом месте; сводки не запускаются, пока кому-то отвечают или ждут. В каждом задании используется один PHP-воркер: на общем хостинге не превышайте половину общего лимита рабочих на ваших сайтах (например, 20–30 из 60 рабочих).',
  'Yalnız cevaplara ayrılan işçi' => 'Рабочие зарезервированы для ответов',
  'Bu kadar işçi hiçbir zaman özet ya da hatırlatıcı almaz.' => 'Многие работники никогда не принимают конспекты и напоминания.',
  'Özet saatleri' => 'Суммарные часы',
  'Özetler yalnız bu saatler arasında yapılır (elle "Şimdi özetle" hariç). İkisi aynıysa her saat.' => 'Сводки публикуются только в эти часы (кроме инструкции «Подвести итоги сейчас»). Если оба одинаковы, в любое время.',
  'Kişi sesli mesaj gönderirse asistan sesi metne çevirip cevap versin (metin panelde sistem satırı olarak da görünür)' => 'Когда кто-то отправляет голосовое сообщение, помощник преобразует его в текст и отвечает (текст также отображается в панели в виде системной строки)',
  'En uzun ses (sn)' => 'Самое длинное голосовое сообщение (сек)',
  'Daha uzun seslerde asistan "ses çok uzun olduğu için dinleyemedik" der.' => 'В случае более длинных сообщений помощник говорит: «Голосовое сообщение было слишком длинным, чтобы мы могли его прослушать».',
  'Sesli mesaj modeli (isteğe bağlı)' => 'Модель голосового сообщения (необязательно)',
  'Ses okuyan ucuz model (Gemini Flash Lite)' => 'Дешевая аудиомодель (Gemini Flash Lite)',
  'Ses okuyan bir OpenRouter modeli olmalı (Claude ses okumaz). OpenRouter anahtarı gerekir.' => 'Должна быть модель OpenRouter, которая принимает аудио (Клод не принимает). Требуется ключ OpenRouter.',
  'Görseller' => 'Изображения',
  'Gerekince asistan görsel (tablo, rapor, şema) çizsin; WhatsApp\'a resim olarak gider, metin ayrıca gider' => 'Пусть помощник нарисует изображение, когда это будет полезно (таблица, отчет, диаграмма); в WhatsApp он отправляется в виде картинки, текст отправляется отдельно',
  'Flux AI görsel çeviricisi kullanılır (Flux AI & MCP › Ayarlar › Görseller).' => 'Используется рендеринг изображений Flux AI (Flux AI & MCP › Настройки › Изображения).',
  'Sunucuda görsel çevirici yok: Flux AI & MCP › Ayarlar › Görseller\'e Gotenberg adresi girin ya da Imagick (SVG) kurulsun. O zamana kadar asistan görsel çizmez.' => 'На сервере нет средства рендеринга изображений: введите адрес Готенберга в Flux AI & MCP › Настройки › Изображения или установите Imagick (SVG). До этого момента помощник не рисует изображения.',
  'Flux AI 0.2.0 ya da sonrası kurulunca çalışır.' => 'Работает после установки Flux AI 0.2.0 или новее.',
  'Başkası adına bağış' => 'Пожертвование от имени кого-либо',
  'Bağış başkası adınaysa ve o kişinin numarası verildiyse (kişi kartı ya da yazılı numara), ödeme onaylanınca sertifika o numaraya da WhatsApp\'tan gitsin' => 'Если пожертвование сделано на чье-то имя и был указан его номер (контактная карточка или введенный номер), также отправьте сертификат на этот номер в WhatsApp после подтверждения платежа.',
  'Sertifikadan önce giden mesaj' => 'Сообщение отправлено перед сертификатом',
  'Ardından Flux Certificates\'daki WhatsApp sertifika mesajı gider. Değişkenler: {ad}, {bagisci}, {bagis}, {brand}.' => 'Затем отправляется сообщение сертификата WhatsApp от Flux Certificates. Переменные: {ad}, {bagisci}, {bagis}, {brand}.',
  'Kişi isterse asistan hatırlatıcı kurar (ör. "her ay fidan dikimini hatırlat", "her ay son projelerinizi gönderin", "her ay benden bir fidan iste"); zamanı gelince asistan mesajı yazıp gönderir' => 'Если человек спрашивает, помощник устанавливает напоминание (например, «напоминай мне о посадке саженцев каждый месяц», «присылай мне свои последние проекты каждый месяц», «проси у меня саженец каждый месяц»); когда наступит срок, помощник напишет и отправит сообщение',
  'Saat söylenmezse' => 'Когда времени не дано',
  'Kişi başına en fazla' => 'Максимум на человека',
  'Personel (Flux Roles)' => 'Персонал (роли Flux)',
  'Flux Roles 1.1.0 kurulunca çalışır: numarası Profil › WhatsApp numarası alanına yazılmış kullanıcılar asistanda yetkilerine göre ek araçlar kullanır.' => 'Работает после установки Flux Roles 1.1.0: пользователи, номер которых указан в Профиле › Номер WhatsApp, получают дополнительные вспомогательные инструменты в зависимости от их разрешений.',
  'Personel numarasından yazana asistan yetkisine göre ek araçlar açsın (başkası adına bağış ve ödeme linki, bağışçılarım, genel rapor)' => 'Предоставьте сотрудникам дополнительные вспомогательные инструменты с разрешения (пожертвование от имени человека, у которого есть ссылка на оплату, моих доноров, общий отчет)',
  'Referansı olduğu bağış ödenince ya da iptal olunca personele WhatsApp bildirimi gitsin' => 'Уведомляйте сотрудников в WhatsApp, когда пожертвование, на которое они ссылаются, оплачено или отменено.',
  'Personel adına açılan bağışta bağışçıya ilk mesaj' => 'Первое сообщение донору о пожертвовании, открытое сотрудниками',
  'Merhaba {ad} 🌱 {personel} aracılığıyla {bagis} bağış talebiniz alındı. Ödemeyi aşağıdaki bilgilerle yapabilirsiniz.' => 'Привет, {ad}🌱 Ваш запрос на пожертвование {bagis} через {personel} получен. Вы можете оплатить по реквизитам ниже.',
  'Ardından ödeme linki ve havale bilgileri gider. Değişkenler: {ad}, {adsoyad}, {personel}, {bagis}.' => 'Далее следует ссылка для оплаты и банковские реквизиты. Переменные: {ad}, {adsoyad}, {personel}, {bagis}.',
  'Personelin referansı olduğu bağış ödenip sertifika oluşunca sertifika personele de WhatsApp\'tan gitsin (bağışçıya gittiği gibi)' => 'Когда пожертвование, указанное сотрудником, будет оплачено и получены сертификаты, отправьте их также сотруднику в WhatsApp (так же, как и донору).',
  'Personele sertifikadan önce giden mesaj' => 'Сообщение, отправленное сотруднику перед сертификатом',
  'Değişkenler: {ad}, {bagisci}, {bagis}, {no}, {brand}.' => 'Переменные: {ad}, {bagisci}, {bagis}, {no}, {brand}.',
  'Personel bir bağışın sertifikasını en fazla kaç kez yeniden gönderebilir' => 'Сколько раз сотрудники могут повторно отправить сертификат о пожертвовании',
  'Asistan göndermeden önce kime gideceğini yazıp onay ister. 0: kapalı.' => 'Помощник перечисляет получателей и запрашивает подтверждение перед отправкой. 0: выкл.',
  'Kayıt sorgusunda kod doğrulama' => 'Проверка кода для поиска записей',
  'Kişi kayıtlarını sorar ve numarası gizliyse (ya da başka numara/e-postayla bağış yaptıysa) verdiği numaraya ya da e-postaya kod gönder; kod doğrulanınca onun kayıtları da gösterilir' => 'Когда человек запрашивает свои записи, а его номер скрыт (или он сделал пожертвование с помощью другого номера/электронной почты), отправьте код на указанный им номер или адрес электронной почты; после проверки его записи также отображаются',
  'Kod geçerliliği (dk)' => 'Срок действия кода (мин)',
  'En fazla başarısız deneme' => 'Максимальное количество неудачных попыток',
  'Gönderilemeyen, yanlış ya da süresi dolan kodlar sayılır. Sınırda kişiye aşağıdaki mesaj gider, ekibe haber verilir; asistan diğer sorulara cevap verir ama 24 saat kayıt bilgisi vermez.' => 'Учитываются коды, которые не удалось отправить, неправильные коды и коды с истекшим сроком действия. При достижении лимита человек получает сообщение ниже, и команда уведомляется; помощник продолжает отвечать на другие вопросы, но не сообщает никаких подробностей в течение 24 часов.',
  'Telefona kod' => 'Код на телефон',
  'WhatsApp, gitmezse SMS' => 'WhatsApp, SMS, если не получится',
  'Yalnız WhatsApp' => 'только WhatsApp',
  'Yalnız SMS' => 'только СМС',
  'SMS, Flux Mail\'te SMS bağlantısı (ör. Netgsm) varsa kullanılır.' => 'SMS используется, если Flux Mail имеет SMS-соединение (например, Netgsm).',
  'Doğrulama yapılamazsa giden mesaj' => 'Сообщение при неудачной проверке',
  'WhatsApp/SMS kod mesajı' => 'Кодовое сообщение WhatsApp/SMS',
  'Boşsa varsayılan metin. Değişkenler: {kod}, {dk}, {marka}. E-posta metni Flux Mail › E-posta şablonları\'ndan değişir.' => 'Текст по умолчанию, если он пуст. Переменные: {kod}, {dk}, {marka}. Текст электронного письма редактируется в Flux Mail › Шаблоны электронной почты.',
  'Sitedeki içerikler' => 'Содержание сайта',
  'Asistan sitede yayında olan içeriklerde arama yapabilsin (ör. "fidan dikimi geçen bir gönderiniz var mı")' => 'Разрешите помощнику выполнять поиск по опубликованному контенту сайта (например, «есть ли у вас запись о посадке деревьев»).',
  'Aranacak içerik türleri' => 'Типы контента для поиска',
  'Yalnız yayında ve şifresiz içerikler döner. Taslak, özel ve şifreli içerik hiçbir zaman gösterilmez.' => 'Возвращается только опубликованный контент без пароля. Черновики, личный контент и контент, защищенный паролем, никогда не отображаются.',
  'Hiç paylaşılmayacak kategori ve etiketler' => 'Категории и теги, которыми нельзя делиться',
  'ör. kurumsal-teklifler, ic-duyuru' => 'например корпоративные предложения, внутреннее уведомление',
  'Ad ya da kısa ad, virgülle. Tek bir içeriği gizlemek için düzenleme ekranındaki "Asistan bu içeriği kişilerle paylaşmasın" kutusunu işaretleyin.' => 'Имя или номер, разделенные запятой. Чтобы скрыть отдельный элемент, установите флажок «Не разрешать помощнику делиться этим содержимым» на экране редактирования.',
