  'listeyi yenileyin' => 'обновить список',
  'Kişilerden gelen mesajları ve verilen cevapları (asistan, ekip, otomatik) bu gruba yaz' => 'Публиковать входящие сообщения и ответы (помощник, команда, автоматические) в эту группу.',
  'Devir bildirimini numaralara ayrı ayrı değil bu gruba gönder; yukarıdaki numaralar mesajda etiketlenir' => 'Отправлять уведомления о передаче обслуживания на эту группу вместо каждого номера; номера выше указаны в сообщении',
