  'Cevap' => 'Ответы',
  'Devir' => 'Передача',
  'Yalnız gerçek sohbetler sayılır; test sohbeti ve benchmark hariç. "Onaylanan" asistanın açtığı ve ödendi işaretlenen bağışlardır.' => 'Учитываются только реальные чаты; тестовый чат и тест исключены. «Подтверждено» означает пожертвования, созданные помощником и помеченные как оплаченные.',
  'Asistanın yazdığı sohbet' => 'Чаты, в которых писал помощник',
  'Ekipte / beklemede' => 'С командой/на паузе',
  'Bağış kaydı açılan' => 'Запись о пожертвовании создана',
  'Asistan henüz bir sohbete cevap vermedi.' => 'Ассистент еще не ответил ни в один чат.',
  'Daha fazla' => 'Загрузить больше',
  'Sohbet kapalı' => 'Chat closed',
