  'Sürüm {id}' => 'Версия {id}',
  'Değişiklik notu (ör. Kurban sorusu eklendi)' => 'Примечание об изменении (например, добавлен вопрос о жертвоприношении)',
  'Asistan talimatı' => 'Инструкции помощника',
  'Asistanın nasıl konuşacağını ve akışı anlatan ana metin. Fiyatlar, bağış türleri, banka bilgisi ve kişinin bilinen bilgileri her cevapta otomatik eklenir. {brand} kurum adına, {{belge:kisa-ad}} o belgenin içeriğine dönüşür.' => 'Основной текст, описывающий, как говорит ассистент и как он движется. Цены, типы пожертвований, банковские реквизиты и сведения о контакте добавляются автоматически при каждом ответе.{brand} становится названием организации, а {{belge:kisa-ad}} становится содержимым этого документа.',
  'Hemen yayına al' => 'Опубликовать сейчас',
  'Yeni sürüm kaydedildi' => 'Новая версия сохранена.',
  'Yeni sürüm olarak kaydet' => 'Сохранить как новую версию',
