  'Yayına al' => 'Опубликовать',
  'Sunucunun gönderdiği hazır mesajlar' => 'Готовые сообщения, отправленные сервером',
  'Bu mesajları model yazmaz; ayarlardaki bilgilerden üretilir.' => 'Модель этого не пишет; они генерируются из ваших настроек.',
  'Ayarlarda değiştir' => 'Изменение настроек',
  '(boş)' => '(пусто)',
  'Modele giden tam metin (örnek sohbet)' => 'Полный текст отправлен модели (пример чата)',
  'Ek belgeler' => 'Дополнительные документы',
  'Sık sorulan sorular, kampanya, dikim yerleri gibi bilgileri ayrı belgeler olarak ekleyin. Talimatta {{belge:kisa-ad}} yazarsanız belge oraya konur. "Gerektiğinde okur" seçilen belgeyi asistan yalnız konu açılınca okur; uzun belgeler için daha az maliyetlidir.' => 'Добавляйте часто задаваемые вопросы, кампании, места посадки и аналогичную информацию в отдельные документы. Если в инструкции написать {{belge:kisa-ad}}, документ помещается туда. Документ, настроенный на «чтение при необходимости», читается только тогда, когда возникает тема, что обходится дешевле для длинных документов.',
  'Yeni belge' => 'Новый документ',
  'Henüz belge yok.' => 'Документов пока нет.',
