  'Sıfırla' => 'Сброс',
  'Fiyatlar 1M token başına giriş / çıkış (USD). Seçilen model yalnız burada kullanılır.' => 'Цены указаны на вход/выход за 1 миллион токенов (USD). Выбранная модель используется только здесь.',
