  'Bu oturum silinsin mi? Geri alınamaz.' => 'Удалить этот сеанс? Это невозможно отменить.',
  'Bu oturumdan sonra yayındaki talimat değişti; yeni bir oturum açmanız önerilir.' => 'После этого сеанса живые инструкции изменились; рекомендуется начать новый сеанс.',
  'Neyi değiştirmek istediğinizi yazın. Bir kişinin ya da numaranın sohbetinden bahsederseniz yapay zekâ sohbeti bulur, okumak için sizden izin ister, talimatı günceller ve sağdaki test sohbetinde kendisi dener. Yayına almak sizin onayınızla olur.' => 'Напишите, что вы хотите изменить. Если вы упоминаете чат человека или номера, ИИ находит его, спрашивает вашего разрешения на чтение, обновляет инструкции и сам пробует их в тестовом чате справа. Публикация требует вашего одобрения.',
