  'Önce yazan kişilere cevap verilir; cevap yazılan ya da sırada bekleyen kişi varken özet başlamaz. {h} saat sessiz kalan sohbetler yalnız {w} arasında özetlenir. Aynı anda en fazla {m} iş çalışır, {r} işçi yalnız cevaplara ayrılır (benchmark bir iş sayılır). 5 sn\'de bir yenilenir.' => 'Пишущим отвечают первыми; сводка не начинается, пока кому-то отвечают или ждут. Чаты, молчащие в течение {h} часов, суммируются только между {w}. В большинстве случаев {m} задания выполняются одновременно, работники {r} зарезервированы для ответов (тест считается за один). Обновляется каждые 5 с.',
