  'Sonda durum' => 'Конечное состояние',
  'Konuşma bitince test durumuna bakılır (bağış açıldı mı, iptal edildi mi, kod gitti mi…). Bu sitede kapalı araç bakılmaz.' => 'По окончании разговора проверяется состояние теста (было ли открыто пожертвование, отменено, отправлен код...). Инструменты, отключенные на этом сайте, не проверяются.',
