  'Henüz denenmedi. "Bağlantıyı test et" düğmesine basın.' => 'Еще не тестировался. Нажмите «Проверить соединение».',
  'Telefon bağlı değil (durum: %1$s, %2$s). "QR ile bağla" ile yeniden bağlayın.' => 'Телефон не подключен (состояние: %1$s, %2$s). Повторно подключитесь с помощью «Подключиться с помощью QR».',
  '%s: Evolution API sürümü' => '%s: версия API эволюции.',
  'Evolution API %s kullanılıyor. Gizli numaralı (@lid) kişilere cevap gitmeyebilir; sunucuyu 2.3 veya üstüne güncelleyin.' => 'Используется Evolution API %s. Ответы на контакты со скрытым номером (@lid) могут не получиться; обновите сервер до версии 2.3 или новее.',
  '%s: webhook (gelen mesajlar)' => '%s: вебхук (входящие сообщения)',
