  'Son olay %s geldi. Hat sessiz olabilir; emin olmak için kendinize mesaj atın ya da webhook\'u yeniden kurun.' => 'Последнее событие прибыло %s. На линии может быть просто тихо; отправьте себе сообщение или настройте вебхук еще раз, чтобы быть уверенным.',
  'Son olay %s geldi.' => 'Последнее событие прибыло %s.',
  'Flux Mail entegrasyonu' => 'Интеграция Flux Mail',
  'Etkin: WhatsApp bağlantıları İletişim › Bağlantılar\'dan alınır.' => 'Активно: соединения WhatsApp берутся из раздела Общение › Соединения.',
  'Flux Mail etkin değil; bağlantılar Flux Certificates\'dan ya da bu eklentiden alınır.' => 'Flux Mail не активен; подключения берутся из Flux Certificates или из этого плагина.',
  'Flux Certificates entegrasyonu' => 'Интеграция сертификатов Flux',
  'Etkin: sohbetten sertifika oluşturulup gönderilebilir.' => 'Активно: сертификаты можно создавать и отправлять из чатов.',
  'Flux Certificates etkin değil; sohbetten sertifika işlemleri kapalı.' => 'Сертификаты Flux не активны; действия с сертификатами в чатах отключены.',
  'Flux Donate entegrasyonu' => 'Интеграция Flux Donate',
  'Etkin: sohbetten bağış kaydı, dekont eşleştirme ve asistan kullanılabilir.' => 'Активно: записи пожертвований, сопоставление квитанций и помощник доступны из чатов.',
  'Flux Donate etkin değil; bağış kaydı, dekont eşleştirme ve bağış asistanı kapalı.' => 'Flux Donate не активен; записи пожертвований, сопоставление квитанций и помощник по пожертвованиям отключены.',
  'Flux AI & MCP eklentisi kurulu değil; yapay zekâ özellikleri (öneri, asistan, dekont okuma, sesli mesaj, özet) kapalı. Flux AI\'yi kurup anahtarı oraya girin.' => 'Плагин Flux AI & MCP не установлен; Функции искусственного интеллекта (предложения, помощник, чтение квитанций, голосовые сообщения, сводки) отключены. Установите Flux AI и введите туда ключ.',
  'Flux AI\'de anahtar girilmemiş; mesaj önerisi ve asistan kapalı.' => 'В Flux AI не был введен ключ; предложения сообщений и помощник отключены.',
  'Anahtar var ama model seçilmemiş.' => 'Ключ сохранен, но модель не выбрана.',
  'Seçili model (%s) için Flux AI\'de sağlayıcının anahtarı girilmemiş.' => 'В Flux AI для выбранной модели не был введен ключ провайдера (%s).',
  'Anahtar kayıtlı, model: %s. Canlı deneme için "Bağlantıyı test et".' => 'Ключ сохранен, модель: %s. Используйте «Тестовое соединение» для проверки в реальном времени.',
  'Bağış asistanı' => 'Помощник по пожертвованиям',
  'Kapalı.' => 'Выкл.',
  'Yapay zekâ anahtarı veya modeli eksik.' => 'Ключ или модель AI отсутствует.',
  'Açık ama konuşmuyor: ' => 'Включаю, но не отвечаю:',
  'Açık. Sunulan bağış türleri: %s.' => 'Вкл. Предлагаемые типы пожертвований: %s.',
  '%s araç (tools) desteklemiyor; asistan için araç destekli bir model seçin.' => '%s не поддерживает инструменты; выберите для помощника модель, поддерживающую инструмент.',
  'Dekont okuma modeli' => 'Модель чтения квитанции',
  '%s görsel okuyamıyor; dekont ön kontrolü çalışmaz. Görsel destekli bir dekont okuma modeli seçin.' => '%s не может читать изображения; предварительная проверка чека не будет работать. Выберите модель чтения квитанций с возможностью изображения.',
  'Asistanın ödeme bilgileri' => 'Платежные реквизиты помощника',
  'Alıcı adı ve IBAN tanımlı.' => 'Имя получателя и набор IBAN.',
  'Alıcı adı veya IBAN eksik; onaydan sonra havale bilgisi gönderilemez.' => 'Имя получателя или IBAN отсутствуют; Банковские реквизиты не могут быть отправлены после подтверждения.',
  'Bağış sayfası linki' => 'Ссылка на страницу пожертвований',
  'Bağış sayfası bulunamadı; asistan link göndermez.' => 'Страница пожертвования не найдена; помощник не отправит ссылку.',
  'Arka plan istekleri' => 'Фоновые запросы',
  'Site kendine arka plan isteği atamadı (%1$s: %2$s). Sıradaki cevaplar ve benchmark yavaş ilerleyebilir; güvenlik eklentisi ya da sunucu güvenlik duvarı /wp-json/flx-chat/ isteklerini engelliyor olabilir.' => 'Сайт не смог отправить себе фоновый запрос (%1$s: %2$s). Ответы в очереди и контрольный показатель могут двигаться медленно; плагин безопасности или брандмауэр сервера могут блокировать запросы /wp-json/flx-chat/.',
  'hata' => 'ошибка',
  'uyarı' => 'предупреждение',
  'tamam' => 'ок',
  '{marka} doğrulama kodunuz: {kod}' => 'Ваш код подтверждения {marka}: {kod}.',
  'Kod {dk} dakika geçerlidir. Bu kodu WhatsApp\'ta bizimle olan sohbete yazın. Bu isteği siz yapmadıysanız dikkate almayın.' => 'Код действителен в течение {dk} минут. Введите его в свой чат WhatsApp с нами. Если вы не просили об этом, проигнорируйте это сообщение.',
  'Bir sıkıntı oldu, ekibimiz en kısa sürede sizinle iletişime geçecek 🌱 Bu arada başka bir sorunuz olursa yazabilirsiniz.' => 'Что-то пошло не так; наша команда свяжется с вами как можно скорее 🌱 А пока не стесняйтесь спрашивать что-нибудь еще.',
  'Doğrulama denemesi başarısız (%1$d/%2$d): %3$s' => 'Попытка проверки не удалась (%1$d/%2$d): %3$s.',
  'Kişi kayıtlarını görmek istedi, doğrulama yapılamadı; ekipten biri iletişime geçmeli' => 'Человек хотел просмотреть свои записи, но его не удалось проверить; кто-то из команды должен связаться',
  'e-posta gönderilemedi (Flux Mail › SMTP ayarlarını kontrol edin)' => 'Не удалось отправить электронное письмо (проверьте Flux Mail › настройки SMTP)',
  'Asistan %1$s için doğrulama kodu gönderdi (%2$s).' => 'Ассистент отправил код подтверждения для %1$s(%2$s).',
  'kodun süresi doldu' => 'срок действия кода истек',
  'yanlış kod' => 'неправильный код',
  'Kişi %s için kodu doğruladı; kayıt sorgusuna eklendi.' => 'Человек проверил код %s; он добавляется в их поиск по записям.',
  'Claude modelleri ses okuyamaz; Ayarlar › Yapay zekâ › Sesli mesaj modelinden ses okuyan bir OpenRouter modeli seçin.' => 'Модели Claude не могут читать аудио; выберите модель OpenRouter с поддержкой аудио в меню «Настройки» > «AI» > «Модель голосового сообщения».',
  'Ses metne çevrilemedi.' => 'Звук не удалось расшифровать.',
  'Ses dosyası okunamadı.' => 'Аудиофайл не может быть прочитан.',
  'Sesli mesaj (%1$s) metne çevrildi: %2$s' => 'Голосовое сообщение (%1$s) расшифровано: %2$s',
  'Sesli mesaj (%1$s) dinlenemedi: %2$s' => 'Голосовое сообщение (%1$s) не удалось обработать: %2$s.',
  'Resmi WhatsApp Cloud API hattında bu işlem yok.' => 'Это действие недоступно в официальной строке WhatsApp Cloud API.',
  'WhatsApp 24 saat kuralı: kişi son 24 saatte yazmadığı için Cloud API serbest mesaj göndermiyor; yalnız onaylı şablon gider. Kişi yazınca yeniden deneyin.' => 'Правило 24 часов в WhatsApp: контакт не писал в течение последних 24 часов, поэтому Cloud API не будет отправлять сообщение в свободной форме; можно отправить только утвержденный шаблон. Попробуйте еще раз, как напишут.',
  'Cloud API hattı için Flux Mail 1.10.0 veya üstü gerekli.' => 'Для линии Cloud API требуется Flux Mail 1.10.0 или новее.',
  'Cloud API bu adrese (gizli numara ya da grup) gönderemez.' => 'Cloud API не может отправить сообщение на этот адрес (скрытый номер или группу).',
  'Cloud API hesabına ulaşılamadı (İletişim › Bağlantılar).' => 'Не удалось получить доступ к учетной записи Cloud API (İletişim › Connections).',
  'Cloud API hattında QR yok; hesap İletişim › Bağlantılar\'da kurulur.' => 'Линия Cloud API не имеет QR-кода; учетная запись настроена в İletişim › Connections.',
  'Dosya hazırlanamadı.' => 'Не удалось подготовить файл.',
  'Flux AI görsel desteği yok.' => 'Flux AI не поддерживает изображения.',
  'Görsel çevrilemedi.' => 'Изображение не удалось отобразить.',
  'Asistanın görseli gönderilemedi: ' => 'Не удалось отправить изображение помощника:',
  'Merhaba {first_name}, bağış kaydınızı oluşturduk: {donation}, toplam {amount}.' . chr(10) . '' . chr(10) . '{bank}' . chr(10) . '' . chr(10) . 'Ödemeyi yaptıktan sonra dekontu buradan gönderebilirsiniz. Teşekkür ederiz.' => 'Здравствуйте, {first_name}, мы создали запись о вашем пожертвовании: {donation}, общая сумма {amount}.{bank} После оплаты вы можете отправить чек сюда. Спасибо.',
  'Merhaba {first_name}, bağışınız kaydedildi: {donation}, toplam {amount}.' . chr(10) . '' . chr(10) . 'Desteğiniz için teşekkür ederiz.' => 'Здравствуйте, {first_name}, ваше пожертвование зарегистрировано: {donation}, общая сумма {amount}.' . chr(10) . '' . chr(10) . 'Спасибо за вашу поддержку.',
  'Bu senaryoyu oynatacak eklenti kapalı.' => 'Плагин, который будет запускать этот сценарий, неактивен.',
  'Bu kullanıcının personel araçları yetkisi yok.' => 'Этому пользователю не разрешено использовать штатные инструменты.',
  '%1$s bu sohbeti personel olarak bağladı: %2$s' => '%1$s связал этот чат с сотрудником %2$s',
  '%s sohbetin personel bağlantısını kaldırdı' => '%s удалил ссылку на персонал этого чата.',
  'Sohbet personele bağlandı' => 'Чат связан с сотрудником',
  'Personel bağlantısı kaldırıldı' => 'Ссылка на персонал удалена',
  '— Personel değil —' => '— Не персонал —',
  'WhatsApp bu kişinin numarasını gizliyor, asistan personeli numaradan tanıyamaz. Bu kişi ekibinizdense buradan bağlayın; asistan personel araçlarını açar.' => 'WhatsApp скрывает номер этого человека, поэтому помощник не может распознать сотрудника по номеру. Если этот человек входит в вашу команду, свяжите его здесь, и помощник откроет инструменты для персонала.',
  'Asistan personeli Flux Roles profilindeki numaradan tanır. Numara eşleşmiyorsa buradan bağlayabilirsiniz; numarası bilinen sohbette numara önceliklidir.' => 'Ассистент узнает сотрудников по номеру в их профиле ролей Flux. Если номера не совпадают, вы можете связать их здесь; в чате с известным номером номер стоит первым.',
  'Bu kanal şu an kullanılamıyor.' => 'Этот канал сейчас недоступен.',
  'Site sohbeti' => 'Чат на сайте',
  'WhatsApp, site sohbeti ve diğer kanallardan gelen tüm mesajlar burada canlı görünür. Soldan bir sohbet seçin.' => 'Все сообщения из WhatsApp, чата сайта и других каналов отображаются здесь в прямом эфире. Выберите чат слева.',
  'WhatsApp (Evolution API) çağrı merkezi: gelen ve giden mesajları canlı görün, yeni sohbet başlatın, hazır cevaplar, etiketler, atama, dahili notlar, otomatik yanıtlar; sohbetten bağış (Flux Donate) ve sertifika (Flux Certificates) kaydı, dekont eşleştirme. OpenRouter ile yapay zekâ cevap önerisi ve otomatik bağış asistanı.' => 'Колл-центр WhatsApp (Evolution API): просмотр входящих и исходящих сообщений в реальном времени, запуск нового чата, готовые ответы, теги, назначения, внутренние заметки, автоответы; Регистрация пожертвований (Flux Donate) и сертификатов (Flux Certificates) из чата, сопоставление квитанций. Предложение ответа искусственного интеллекта и автоматический помощник по пожертвованиям с OpenRouter.',
  'WhatsApp (Evolution API) call center: see live incoming and outgoing messages, start new chat, canned replies, tags, assignment, internal notes, auto-replies; Donation (Flux Donate) and certificate (Flux Certificates) registration from chat, receipt matching. Artificial intelligence response suggestion and automatic donation assistant with OpenRouter.' => 'Колл-центр WhatsApp (Evolution API): просмотр входящих и исходящих сообщений в реальном времени, запуск нового чата, готовые ответы, теги, назначения, внутренние заметки, автоответы; Регистрация пожертвований (Flux Donate) и сертификатов (Flux Certificates) из чата, сопоставление квитанций. Предложение ответа искусственного интеллекта и автоматический помощник по пожертвованиям с OpenRouter.',
  'Hide' => 'Скрыть',
  'Show' => 'Показать',
  'Deleted for everyone' => 'Удалено у всех',
  'Hidden in the panel' => 'Скрыто в панели',
  'Delete for everyone' => 'Удалить у всех',
  'Hide in the panel only' => 'Скрыть только в панели',
  'WhatsApp doesn\'t allow deleting a received message for everyone; it stays on the contact\'s phone and is only hidden in the panel.' => 'WhatsApp не позволяет удалить полученное сообщение у всех; оно останется на телефоне контакта и будет скрыто только в панели.',
  'Delete for everyone is turned off in the settings; the message is only hidden in the panel and stays on the contact\'s phone.' => 'Удаление у всех отключено в настройках; сообщение будет скрыто только в панели и останется на телефоне контакта.',
  'This channel doesn\'t support delete for everyone; the message is only hidden in the panel and stays on the contact\'s phone.' => 'Этот канал не поддерживает удаление у всех; сообщение будет скрыто только в панели и останется на телефоне контакта.',
  'The time limit for delete for everyone has passed (WhatsApp allows about {h} hours after sending). The message stays on the contact\'s phone and is only hidden in the panel.' => 'Срок удаления у всех истёк (WhatsApp позволяет около {h} ч после отправки). Сообщение останется на телефоне контакта и будет скрыто только в панели.',
  'Only the sender or an administrator can delete this message for everyone; you can hide it in the panel.' => 'Удалить это сообщение у всех может только отправитель или администратор; вы можете скрыть его в панели.',
  'If deleted for everyone, the message also turns into "This message was deleted" on the contact\'s phone. Time left: about {n} hours.' => 'При удалении у всех на телефоне контакта тоже появится «Это сообщение удалено». Осталось: около {n} ч.',
  'Deleted messages are kept on the server: the chat shows a "This message was deleted" line and the team can click it to see the content. AI does not read deleted messages.' => 'Удалённые сообщения хранятся на сервере: в чате видна строка «Это сообщение удалено», команда может нажать и увидеть содержимое. ИИ не читает удалённые сообщения.',
  'Message not found.' => 'Сообщение не найдено.',
  'This message was already deleted.' => 'Это сообщение уже удалено.',
  'Only the sender or an administrator can delete this message for everyone.' => 'Удалить это сообщение у всех может только отправитель или администратор.',
  'This message can\'t be deleted for everyone on this channel. You can hide it in the panel instead.' => 'В этом канале сообщение нельзя удалить у всех. Вместо этого его можно скрыть в панели.',
  'The time limit for deleting for everyone has passed. You can hide it in the panel instead.' => 'Срок удаления у всех истёк. Вместо этого сообщение можно скрыть в панели.',
  'WhatsApp did not delete the message.' => 'WhatsApp не удалил сообщение.',
  'Delete for everyone time limit (hours)' => 'Срок удаления у всех (часы)',
  'WhatsApp lets you delete a sent message for everyone only for about 2 days and 12 hours (60 hours). After this limit, or for received messages, the message is only hidden in the panel: it stays on the contact\'s phone. 0 turns off delete for everyone. Deleted messages are never removed from the server; the team can still open them.' => 'WhatsApp позволяет удалить отправленное сообщение у всех только в течение примерно 2 дней и 12 часов (60 часов). После этого срока, а также для полученных сообщений, сообщение только скрывается в панели и остаётся на телефоне контакта. 0 отключает удаление у всех. Удалённые сообщения никогда не удаляются с сервера; команда может их открыть.',
  'Last update request %1$s. While the panel is open it checks for new messages every %2$d s (3 s while a reply is streaming, up to 15 s when nothing changes) and once a minute in a background tab.' => 'Последний запрос на обновление %1$s. Пока панель открыта, она проверяет новые сообщения каждые %2$d с (3 с, пока идёт поток ответа, и до 15 с, если ничего не меняется) и раз в минуту на фоновой вкладке.',
  'The open tab checks for new messages at this interval (10 recommended), every 3 s while a reply is streaming, and up to 15 s when nothing changes. A background tab checks once a minute. Errors back off up to 60 s.' => 'Открытая вкладка проверяет новые сообщения с этим интервалом (рекомендуется 10), каждые 3 с, пока идёт поток ответа, и до 15 с, если ничего не меняется. Фоновая вкладка проверяет раз в минуту. После ошибок интервал увеличивается до 60 с.',
  'Flux Donate is not active.' => 'Flux Donate не активен.',
  'Donor\'s earlier referral' => 'Прежний реферал жертвователя',
  'Referral' => 'Реферал',
  'Order' => 'Заказ',
  'Confirmation code' => 'Код подтверждения',
  'Recorded from' => 'Источник записи',
  'Entered by' => 'Внёс',
  'Items' => 'Позиции',
  'On behalf of: {n}' => 'От имени: {n}',
  'Receipts' => 'Квитанции',
  'Revoked' => 'Отозван',
  '{n} paid gifts · {m}' => 'Оплачено пожертвований: {n} · {m}',
  'No contact details.' => 'Нет контактных данных.',
  'No referral.' => 'Нет реферала.',
  'Has the payment reached the account? When you confirm, the certificate is made and sent to the donor.' => 'Платёж поступил на счёт? После подтверждения сертификат будет создан и отправлен жертвователю.',

 ),
);
